insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values ('9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Ley del Sistema Nacional de Información Estadística y Geográfica','LSNIEG','2008-04-16','2025-11-14',true,ARRAY['SNIEG','INEGI','Información Estadística','Información Geográfica','Información de Interés Nacional','Sector Energético']::text[],'https://www.diputados.gob.mx/LeyesBiblio/pdf/LSNIEG.pdf','ley') on conflict (id) do nothing;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('96acf909-c013-5aee-b27c-84fd0116bd5a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 1','<p>ARTÍCULO 1.- La presente Ley, reglamentaria del Apartado B del artículo 26 de la Constitución Política de los Estados Unidos Mexicanos, es de orden público, de interés social y de observancia general en toda la República, y tiene por objeto regular:</p><p>I. El Sistema Nacional de Información Estadística y Geográfica;</p><p>II. Los derechos y las obligaciones de los Informantes del Sistema;</p><p>III. La organización y el funcionamiento del Instituto Nacional de Estadística y Geografía, y</p><p>IV. Las faltas administrativas y el medio de defensa administrativo frente a los actos o resoluciones del Instituto.</p>','ordinario',1,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('6f481c34-fef3-557c-8242-2637b1966157'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 2','<p>ARTÍCULO 2.- Para efectos de esta Ley se entenderá por:</p><p>I. Actividades Estadísticas y Geográficas o Actividades: las relativas al diseño, captación, producción, actualización, organización, procesamiento, integración, compilación, publicación, divulgación y conservación de la Información de Interés Nacional.</p><p>II. Consejo: al Consejo Consultivo Nacional.</p><p>III. Información Estadística: al conjunto de resultados cuantitativos o datos que se obtienen de las Actividades Estadísticas y Geográficas en materia estadística, tomando como base los datos primarios obtenidos de los Informantes del Sistema sobre hechos que son relevantes para el conocimiento de los fenómenos económicos, gobierno, seguridad pública e impartición de</p><p>justicia; demográficos y sociales, así como sus relaciones con el medio ambiente y el espacio territorial. Fracción reformada DOF 25-06-2018</p><p>IV. Información Geográfica: al conjunto organizado de datos espaciales georreferenciados, que mediante símbolos y códigos genera el conocimiento acerca de las condiciones físico- ambientales, de los recursos naturales y de las obras de naturaleza antrópica del territorio nacional.</p><p>V. Información: Información Estadística y Geográfica de interés nacional.</p><p>VI. Información de Interés Nacional: a la Información que se determine como tal en términos de lo dispuesto en los artículos 77, fracción II y 78 de esta Ley.</p><p>VII. Informantes del Sistema: a las personas físicas y morales, a quienes les sean solicitados datos estadísticos y geográficos en términos de esta Ley.</p><p>VIII. Instituto o INEGI: al Instituto Nacional de Estadística y Geografía.</p><p>IX. Junta de Gobierno: a la Junta de Gobierno del Instituto.</p><p>X. Presidente del Instituto o Presidente: al Presidente del Instituto Nacional de Estadística y Geografía.</p><p>XI. Red Geodésica Nacional: la compuesta por estaciones geodésicas, horizontales, verticales y gravimétricas distribuidas de forma homogénea en el territorio nacional.</p><p>XII. Red Nacional de Información: al conjunto de procesos de intercambio y resguardo de información, para apoyar por un lado las actividades de coordinación del Sistema y de sus Subsistemas y por otro la prestación del Servicio Público de Información a toda la sociedad.</p><p>XIII. Sistema Nacional de Información Estadística y Geográfica o Sistema: al conjunto de Unidades organizadas a través de los Subsistemas, coordinadas por el Instituto y articuladas mediante la Red Nacional de Información, con el propósito de producir y difundir la Información de Interés Nacional.</p><p>XIV. Subsistemas Nacionales de Información o Subsistemas: a los componentes del Sistema enfocados a producir información de una determinada clase o respecto de temas específicos.</p><p>XV. Unidades del Estado o Unidades: a las áreas administrativas que cuenten con atribuciones para desarrollar Actividades Estadísticas y Geográficas o que cuenten con registros administrativos que permitan obtener Información de Interés Nacional de:</p><p>a) Las dependencias y entidades de la Administración Pública Federal, incluyendo a las de la Presidencia de la República. Inciso reformado DOF 20-05-2021</p><p>b) Los poderes Legislativo y Judicial de la Federación;</p><p>c) Las entidades federativas, los municipios y las demarcaciones territoriales de la Ciudad de México; Inciso reformado DOF 19-01-2018</p><p>d) Los organismos constitucionales autónomos, y</p><p>e) Los tribunales administrativos federales.</p><p>Cuando el Instituto genere Información se considerará como Unidad para efectos de esta Ley.</p><p>TÍTULO SEGUNDO DEL SISTEMA NACIONAL DE INFORMACIÓN ESTADÍSTICA Y GEOGRÁFICA</p><p>Del Sistema</p>','ordinario',2,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('927b460b-ca4b-5d4f-b112-17fd37e5159a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 3','<p>ARTÍCULO 3.- El Sistema Nacional de Información Estadística y Geográfica, tiene la finalidad de suministrar a la sociedad y al Estado Información de calidad, pertinente, veraz y oportuna, a efecto de coadyuvar al desarrollo nacional.</p><p>Serán principios rectores del Sistema los de accesibilidad, transparencia, objetividad e independencia.</p>','ordinario',3,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('fd5361b3-ce77-5f66-a0a0-9cd83beec97c'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 4','<p>ARTÍCULO 4.- El Sistema Nacional de Información Estadística y Geográfica tendrá como objetivos:</p><p>I. Producir Información;</p><p>II. Difundir oportunamente la Información a través de mecanismos que faciliten su consulta;</p><p>III. Promover el conocimiento y uso de la Información, y</p><p>IV. Conservar la Información.</p>','ordinario',4,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('39c94e00-198b-5911-9645-7e8ef62f205e'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 5','<p>ARTÍCULO 5.- El Sistema Nacional de Información Estadística y Geográfica estará integrado por:</p><p>I. El Consejo Consultivo Nacional;</p><p>II. Los Subsistemas Nacionales de Información, y</p><p>III. El Instituto.</p>','ordinario',5,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('7f5cf3c8-5857-5234-ada9-622f7f58a6d5'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 6','<p>ARTÍCULO 6.- La Información de Interés Nacional será oficial y de uso obligatorio para la Federación, las entidades federativas, los municipios y las demarcaciones territoriales de la Ciudad de México. Párrafo reformado DOF 19-01-2018</p><p>Sin perjuicio de lo señalado en el párrafo anterior, las Unidades podrán producir y dar a conocer información pública oficial adicional a la Información de Interés Nacional.</p>','ordinario',6,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('b43edb4a-3753-5c5d-a384-6995b4fd5b25'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 7','<p>ARTÍCULO 7.- La organización, la planeación, el funcionamiento y la coordinación de Actividades Estadísticas y Geográficas, así como la evaluación de los resultados del Sistema, se sujetarán a esta Ley, a los programas previstos en el artículo 9 de esta Ley y a las disposiciones de carácter general que expida al efecto el Instituto, de acuerdo con la disponibilidad presupuestaria correspondiente.</p><p>El Instituto expedirá un código de ética que regule los estándares de conducta a los que deberá apegarse todo aquél que realice Actividades Estadísticas y Geográficas, incluyendo al propio Instituto. El código de ética se pondrá a disposición del público a través de Internet.</p>','ordinario',7,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('afb13dca-e6c9-5d56-9cc3-2da8f228e1f1'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 8','<p>ARTÍCULO 8.- Las Unidades del Estado participarán en el Sistema a través de:</p><p>I. El Consejo Consultivo Nacional;</p><p>II. Los Comités Ejecutivos de los Subsistemas, y</p><p>III. Los Comités Técnicos Especializados.</p><p>El Instituto deberá emitir las disposiciones generales para regular el funcionamiento de los órganos colegiados a que se refieren las fracciones anteriores.</p><p>De la Programación</p>','ordinario',8,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('62a3ea39-dfac-5eef-9860-d22d72d1ca37'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 9','<p>ARTÍCULO 9.- La ordenación y regulación de las actividades necesarias para la planeación, programación, producción y difusión de la Información de Interés Nacional, se llevará a cabo a través de los instrumentos siguientes:</p><p>I. El Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica;</p><p>II. El Programa Nacional de Estadística y Geografía, y</p><p>III. El Programa Anual de Estadística y Geografía.</p><p>La Junta de Gobierno tendrá a su cargo la aprobación de los programas a que se refiere este artículo, debiendo someter los proyectos de los mismos para opinión a las instancias respectivas en los términos que señala esta Ley.</p><p>Una vez aprobados el Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica y el Programa Nacional de Estadística y Geografía, deberán ser publicados en el Diario Oficial de la Federación y serán obligatorios para las Unidades del Estado conforme a la disponibilidad presupuestaria correspondiente.</p>','ordinario',9,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('4592b325-1110-5b66-b903-3a85eaee0bd7'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 10','<p>ARTÍCULO 10.- El Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica:</p><p>I. Tendrá una proyección de al menos 24 años y deberá ser revisado y actualizado por la Junta de Gobierno cada seis años, al inicio del cuarto año del periodo correspondiente al Presidente de la República;</p><p>II. Constituirá el instrumento rector para la integración y coordinación del Sistema Nacional de Información Estadística y Geográfica;</p><p>III. Determinará y jerarquizará los objetivos y metas a alcanzar por el Sistema, definiendo las acciones generales necesarias para ello;</p><p>IV. Definirá las políticas que deberán atender los Comités Ejecutivos de los Subsistemas en la realización de las Actividades Estadísticas y Geográficas, y</p><p>V. Deberá considerar las líneas de acción y elementos que propongan las Unidades del Estado y tomará en cuenta la opinión de instituciones sociales y privadas.</p>','ordinario',10,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('f7ec0c2f-870a-5798-b716-fd0cd8713508'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 11','<p>ARTÍCULO 11.- El Programa Nacional de Estadística y Geografía:</p><p>I. Será elaborado cada seis años en congruencia con el Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica y con el Plan Nacional de Desarrollo, una vez que éste se publique en el Diario Oficial de la Federación; debiendo evaluarse y actualizarse al final de cada ejercicio, o cuando se modifique el citado Programa Estratégico;</p><p>II. Definirá el conjunto de actividades y proyectos a ser ejecutados durante cada sexenio presidencial por las Unidades del Estado, en congruencia con lo establecido en el Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica y en el Plan Nacional de Desarrollo en lo relativo a las materias de Información correspondientes a los Subsistemas, y</p><p>III. Se orientará a producir la información tendiente al mejor conocimiento del territorio y de la realidad económica, gobierno, seguridad pública e impartición de justicia. Así como, social y del medio ambiente del país. Fracción reformada DOF 25-06-2018</p>','ordinario',11,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('016c01f8-4444-5746-9c4b-a5b0eb03a677'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 12','<p>ARTÍCULO 12.- El Programa Anual de Estadística y Geografía deberá elaborarse tomando en consideración lo dispuesto en el Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica y en el Programa Nacional de Estadística y Geografía, debiendo comprender las Actividades a desarrollar por cada Subsistema para la generación de la Información de Interés Nacional en el año al que corresponda, de conformidad con lo dispuesto en esta Ley. La ejecución de las Actividades previstas en el Programa Anual de Estadística y Geografía quedará sujeta a la disponibilidad presupuestaria de las Unidades.</p>','ordinario',12,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('210327a6-693e-56e7-a57d-71e26480c357'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 13','<p>ARTÍCULO 13.- El Instituto proporcionará a las autoridades competentes la Información de Interés Nacional que se requiera para la elaboración del Plan Nacional de Desarrollo.</p><p>Del Consejo Consultivo Nacional</p>','ordinario',13,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('bf1794f0-ef29-5ebe-a9f0-63b8370155d4'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 14','<p>ARTÍCULO 14.- El Consejo Consultivo Nacional estará integrado por:</p><p>I. El Presidente del Instituto;</p><p>II. Un representante de cada secretaría de estado de la Administración Pública Federal;</p><p>III. Un representante del Poder Judicial de la Federación;</p><p>IV. Un representante de la Cámara de Diputados del Congreso de la Unión;</p><p>V. Un representante del Senado de la República;</p><p>VI. Cinco representantes de las entidades federativas.</p><p>Las entidades federativas que integren el Consejo Consultivo Nacional serán elegidas por cada uno de los cinco grupos que se señalan a continuación, debiendo representarlos de forma rotativa:</p><p>a) GRUPO SUR - SURESTE: Campeche, Chiapas, Oaxaca, Quintana Roo, Tabasco, Veracruz y Yucatán.</p><p>b) GRUPO CENTRO: Ciudad de México y Estado de México.</p><p>Inciso reformado DOF 19-01-2018</p><p>c) GRUPO CENTRO - NORTE: Aguascalientes, Colima, Durango, Guanajuato, Jalisco, Nayarit, San Luis Potosí y Zacatecas.</p><p>d) GRUPO CENTRO - SUR: Guerrero, Hidalgo, Michoacán, Morelos, Puebla, Querétaro y Tlaxcala.</p><p>e) CENTRO NORTE: Baja California, Baja California Sur, Coahuila, Chihuahua, Nuevo León, Sonora, Sinaloa, y Tamaulipas.</p><p>Las entidades federativas miembros del Consejo durarán en su encargo dos años, pero sus representantes continuarán en funciones, aún después de terminado su periodo, en tanto no sean elegidos los que deban sustituirlos, y</p><p>VII. Un representante del Banco de México, designado al efecto por su Gobernador y un representante del Instituto Federal de Telecomunicaciones designado por su comisionado presidente. Fracción reformada DOF 14-07-2014</p><p>El Instituto podrá invitar a las sesiones del Consejo a representantes de entidades de las administraciones públicas federal y locales e instituciones públicas, sociales y privadas, así como de organismos constitucionales autónomos. Párrafo reformado DOF 14-07-2014</p><p>Los integrantes del Consejo desempeñarán sus funciones en dicho órgano colegiado de manera honoraria.</p>','ordinario',14,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('28484b86-e783-595b-8aea-40f780b034ea'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 15','<p>ARTÍCULO 15.- El Consejo Consultivo Nacional deberá:</p><p>I. Opinar sobre los proyectos de los programas a que se refiere el artículo 9 de esta Ley;</p><p>II. Proponer los temas, la información y los indicadores que, de conformidad con los artículos 77, fracción II y 78 de esta Ley, la Junta de Gobierno determine que habrán de considerarse de Interés Nacional;</p><p>III. Proponer la necesidad de crear los Subsistemas a que se refiere el artículo 17 último párrafo, de esta Ley, y</p><p>IV. Opinar sobre los demás asuntos que someta a su consideración la Junta de Gobierno.</p>','ordinario',15,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('3c599544-3c7b-57ca-a69b-cc972674942e'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 16','<p>ARTÍCULO 16.- El Consejo Consultivo Nacional será presidido por el Presidente del Instituto y fungirá como secretario técnico el servidor público del Instituto que aquél determine.</p><p>El Consejo se reunirá de manera ordinaria al menos una vez al año, y en forma extraordinaria cuando la naturaleza de algún asunto de su competencia así lo exija.</p><p>La convocatoria a reunión del Consejo será formulada por el Presidente del Instituto. Podrán solicitar por escrito al Presidente del Instituto, la convocatoria a una reunión extraordinaria cualquiera de los Comités Ejecutivos de los Subsistemas a través de su Presidente, así como al menos veinticinco por ciento de los miembros del Consejo, con el objeto de tratar alguno de los asuntos a los que se hace referencia en el artículo 15 de esta Ley.</p><p>La convocatoria deberá hacerse con la anticipación necesaria, según la naturaleza y urgencia de los asuntos a tratar. Las reuniones se desahogarán conforme a las reglas que se adopten, a propuesta del Instituto.</p><p>De los Subsistemas Nacionales de Información</p>','ordinario',16,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('09de4b7c-5686-5d29-b764-0af85449627d'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 17','<p>ARTÍCULO 17.- El Sistema contará con los siguientes Subsistemas Nacionales de Información:</p><p>I. Demográfica y Social;</p><p>II.- Económica; Fracción reformada DOF 25-06-2018</p><p>III.- Geográfica y del Medio Ambiente, y Fracción reformada DOF 25-06-2018</p><p>IV.- Gobierno, Seguridad Pública e Impartición de Justicia. Fracción adicionada DOF 25-06-2018</p><p>Cada Subsistema tendrá como objetivo producir, integrar y difundir Información Demográfica y Social; Económica y Financiera, Geográfica y del Medio Ambiente, y de Gobierno, Seguridad Pública e Impartición de Justicia, según corresponda. Párrafo reformado DOF 25-06-2018</p><p>El Instituto deberá emitir las disposiciones generales para regular el funcionamiento de los Subsistemas Nacionales de Información.</p><p>La Junta de Gobierno, previa opinión favorable del Consejo, podrá crear otros Subsistemas que sean necesarios para el adecuado funcionamiento del Sistema.</p>','ordinario',17,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('a41fdc69-2286-50b3-83c3-ff4da96bb084'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 18','<p>ARTÍCULO 18.- En el acuerdo de creación de un Subsistema conforme al último párrafo del artículo anterior, la Junta de Gobierno deberá señalar como mínimo su infraestructura de información, los indicadores clave que deberá producir y las fuentes de las que se obtendrá -con el apoyo de las Unidades- la información básica para dichos indicadores.</p>','ordinario',18,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('0623d27c-9907-5241-9cb9-271c1fa1fd3b'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 19','<p>ARTÍCULO 19.- Formarán parte de los Subsistemas: los Comités Ejecutivos de Información Demográfica y Social, de Información Económica, de Información Geográfica, del Medio Ambiente, y de Información de Gobierno, Seguridad Pública e Impartición de Justicia; los Comités Técnicos Especializados que se constituyan en términos de lo dispuesto en esta Ley, así como las Unidades del Estado. Artículo reformado DOF 25-06-2018</p><p>SECCIÓN I Del Subsistema Nacional de Información Demográfica y Social</p>','ordinario',19,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('092cf39c-8f02-52f7-9c71-2203679c713a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 20','<p>ARTÍCULO 20.- El Subsistema Nacional de Información Demográfica y Social, contará con una infraestructura de información que contenga como mínimo, un marco geoestadístico y un inventario nacional de viviendas.</p>','ordinario',20,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('ef2c42c2-0ac4-5fff-9f47-f1ef94ca0500'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 21','<p>ARTÍCULO 21.- El Subsistema Nacional de Información Demográfica y Social deberá generar un conjunto de indicadores clave, que atenderán como mínimo los temas siguientes: población y dinámica demográfica, salud, educación, empleo, vivienda, distribución de ingreso y pobreza.</p><p>Artículo reformado DOF 25-06-2018</p>','ordinario',21,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('716d8d3b-6368-5b82-9316-f9dd05a58394'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 22','<p>ARTÍCULO 22.- El Instituto elaborará, con la colaboración de las Unidades, los indicadores a que se refiere el artículo anterior, a partir de la información básica que se obtenga de:</p><p>I. El censo nacional de población y vivienda, o de los esquemas alternativos que pudieran adoptarse en el futuro para sustituirlo total o parcialmente;</p><p>II. Un sistema integrado de encuestas nacionales de los hogares, y</p><p>III. Los registros administrativos que permitan obtener Información en la materia.</p><p>SECCIÓN II Del Subsistema Nacional de Información Económica</p>','ordinario',22,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('d01e2ae5-082a-52df-92fb-97d5178d5581'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 23','<p>ARTÍCULO 23.- El Subsistema Nacional de Información Económica, contará con una infraestructura de información que contenga como mínimo, un marco geoestadístico y un Directorio Nacional de Unidades Económicas.</p><p>El Directorio a que se hace referencia en el párrafo anterior, así como las clasificaciones económicas que formen parte del mismo, son de uso obligatorio para la organización de los registros administrativos de los que se pueda obtener Información de Interés Nacional.</p>','ordinario',23,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('a5e84e16-e57b-5fc2-bdb1-2c5dbc296931'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 24','<p>ARTÍCULO 24.- El Subsistema Nacional de Información Económica deberá generar un conjunto de indicadores clave, relacionados como mínimo con lo siguiente: sistema de cuentas nacionales; ciencia y tecnología; información financiera; precios y trabajo.</p>','ordinario',24,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('e899bbf2-484e-5ec9-8630-51b684efe99a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 25','<p>ARTÍCULO 25.- El Instituto elaborará, con la colaboración de las Unidades, los indicadores a que se refiere el artículo anterior a partir de la información básica proveniente de:</p><p>I. Los censos nacionales económicos y agropecuarios, o los esquemas alternativos que pudieran adoptarse en el futuro para sustituirlos total o parcialmente;</p><p>II. Un sistema integrado de encuestas en unidades económicas, y</p><p>III. Los registros administrativos que permitan obtener Información en la materia.</p><p>SECCIÓN III Del Subsistema Nacional de Información Geográfica y del Medio Ambiente</p>','ordinario',25,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('d09dc189-5951-50d1-9929-f29162bf2cee'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 26','<p>ARTÍCULO 26.- El Subsistema Nacional de Información Geográfica y del Medio Ambiente, en su componente geográfico, generará como mínimo los siguientes grupos de datos: marco de referencia geodésico; límites costeros, internacionales, de las entidades federativas, municipales y las demarcaciones territoriales de la Ciudad de México; datos de relieve continental, insular y submarino; datos catastrales, topográficos, de recursos naturales y clima, así como nombres geográficos. A este componente también se le denominará Infraestructura de Datos Espaciales de México.</p><p>Asimismo, emitirá un mapa oficial de la República Mexicana, que incluya las zonas marinas mexicanas, conforme a lo establecido por la Constitución Política de los Estados Unidos Mexicanos y la Ley Federal del Mar, el cual será difundido por el Instituto Nacional de Estadística y Geografía. Párrafo adicionado DOF 01-12-2023</p><p>Las autoridades competentes en materia de límites territoriales proporcionarán al Instituto la información necesaria para la elaboración del mapa. Los conflictos de límites se resolverán a través de las instancias competentes. Párrafo adicionado DOF 01-12-2023 Artículo reformado DOF 19-01-2018</p>','ordinario',26,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('092f1845-df69-5a3e-87e7-a2a55225a3d3'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 27','<p>ARTÍCULO 27.- El Subsistema Nacional de Información Geográfica y del Medio Ambiente, en su componente del medio ambiente, procurará describir el estado y las tendencias del medio ambiente, considerando los medios naturales, las especies de plantas y animales, y otros organismos que se encuentran dentro de estos medios.</p><p>El Subsistema referido en el párrafo anterior, deberá generar, como mínimo, indicadores sobre los siguientes temas: atmósfera, agua, suelo, flora, fauna, residuos peligrosos y residuos sólidos.</p>','ordinario',27,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('a1e902c7-eee4-5e25-a2f3-b6020f41874c'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 28','<p>ARTÍCULO 28.- El Instituto elaborará, con la colaboración de las Unidades, los indicadores a que se refieren los dos artículos anteriores a partir de la información básica proveniente de:</p><p>I. El Sistema Nacional de Información Ambiental y de Recursos Naturales;</p><p>II. Un sistema integrado de inventarios y encuestas sobre recursos naturales y medio ambiente, y</p><p>III. Los registros administrativos que permitan obtener Información en la materia.</p><p>SECCIÓN IV (sic DOF 25-06-2018) Del Subsistema Nacional de Gobierno, Seguridad Pública e Impartición de Justicia Sección adicionada DOF 25-06-2018</p><p>ARTÍCULO 28 BIS.- El Subsistema tendrá como objetivo institucionalizar y operar un esquema coordinado para la producción, integración, conservación y difusión de información estadística y geográfica de interés nacional, de calidad, pertinente, veraz y oportuna que permita conocer la situación que guardan la gestión y el desempeño de las instituciones públicas que conforman el Estado y sus respectivos poderes en las funciones de gobierno, seguridad pública e impartición de justicia, para apoyar los procesos de diseño, implementación, monitoreo y evaluación de las políticas públicas en estas materias. Artículo adicionado DOF 25-06-2018</p><p>ARTÍCULO 28 TER.- El Subsistema contará con una infraestructura de información que integre, como mínimo, un marco geoestadístico, un inventario nacional de registros administrativos, un registro de Unidades del Estado y un inventario de proyectos y productos estadísticos que permitan apoyar la obtención de información oficial respecto a la gestión y desempeño de las instituciones públicas que conforman al Estado y sus respectivos poderes, en las funciones de gobierno, de seguridad pública y de impartición de justicia, según corresponda. Artículo adicionado DOF 25-06-2018</p><p>ARTÍCULO 28 QUÁTER.- El Subsistema Nacional de Gobierno, Seguridad Pública e Impartición de Justicia deberá producir, integrar, administrar, conservar y difundir la información e indicadores clave sobre la gestión y desempeño de las instituciones públicas que conforman al Estado y sus poderes, relacionados, como mínimo, con las funciones de gobierno, seguridad pública e impartición de justicia. Artículo adicionado DOF 25-06-2018</p><p>ARTÍCULO 28 QUINTUS.- El Instituto producirá e integrará, con la colaboración de las Unidades del Estado, la información e indicadores a partir de los datos que se obtengan, entre otras fuentes, de:</p><p>I. Los Censos Nacionales de Gobierno o de los esquemas alternativos que pudieran adoptarse en el futuro para sustituirlos total o parcialmente.</p><p>II. Un registro de Unidades de Estado.</p><p>III. Un sistema integrado de encuestas nacionales relacionado con los temas propios de este Subsistema.</p><p>IV. Los registros administrativos que permitan obtener información en los temas correspondientes.</p><p>La información a la que se refiere esta sección y que pudiera comprometer a la seguridad nacional o a la seguridad pública, será restringida en términos de lo dispuesto en la Ley de Seguridad Nacional y de la fracción IV del artículo 77 de la presente Ley. Artículo adicionado DOF 25-06-2018</p><p>SECCIÓN IV De los Comités de los Subsistemas</p>','ordinario',28,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('85b0a63c-16e6-516c-b919-289762fb0151'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 29','<p>ARTÍCULO 29.- Cada Subsistema contará con un Comité Ejecutivo que se integrará por un Vicepresidente de la Junta de Gobierno, designado por el Presidente del Instituto, quien lo presidirá, y por los coordinadores de las Secretarías que a continuación se señalan para cada Subsistema Nacional de Información: Párrafo reformado DOF 25-06-2018</p><p>I.- Demográfica y Social: Los coordinadores de las secretarías de Gobernación; de Desarrollo Social; de Educación Pública; de Salud, y del Trabajo y Previsión Social, así como de la Comisión Nacional de Seguridad, y del Poder Judicial; Fracción reformada DOF 25-06-2018</p><p>II. Económica: Los coordinadores de las secretarías de Hacienda y Crédito Público, de Economía, del Banco de México y del Instituto Federal de Telecomunicaciones; Fracción reformada DOF 14-07-2014</p><p>III.- Geográfica y del Medio Ambiente: Los coordinadores de las secretarías de la Defensa Nacional; de Marina; del Medio Ambiente y Recursos Naturales; de Energía, y de Agricultura, Ganadería, Desarrollo Rural, Pesca y Alimentación; Fracción reformada DOF 25-06-2018</p><p>IV.- Gobierno, Seguridad Pública e Impartición de Justicia: Los coordinadores de las secretarías de Gobernación; de la Función Pública; de Hacienda y Crédito Público; de la Defensa Nacional y de Marina; de la Comisión Nacional de Seguridad; por el representante del Poder Judicial de la Federación, de la Fiscalía General de la República y del Secretariado Ejecutivo del Sistema Nacional de Seguridad Pública, así como por los representantes del grupo de entidades federativas a que se refiere esta Ley, a través de las instituciones responsables de la información y temas relacionados con la gestión de las instituciones públicas en los temas de gobierno, seguridad pública e impartición de justicia. Fracción adicionada DOF 25-06-2018. Reformada DOF 20-05-2021</p><p>Por acuerdo de la mayoría de los miembros de cada Comité Ejecutivo, se podrá invitar a participar como miembro del mismo a representantes de otras Unidades o determinarse la necesidad de reducir el número de miembros.</p><p>A las sesiones de los Comités a que se refiere este artículo podrán asistir los invitados que cada Comité determine.</p><p>El Instituto nombrará al servidor público -del propio Instituto- que fungirá como secretario técnico en cada uno de los Comités a que se refiere este artículo.</p><p>Los integrantes de los Comités Ejecutivos desempeñarán sus funciones en dichos órganos colegiados de manera honoraria.</p>','ordinario',29,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('1c3fa8c9-c602-5680-a89b-7794e4f61c55'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 30','<p>ARTÍCULO 30.- Los Comités Ejecutivos tendrán las facultades siguientes:</p><p>I. Dar a conocer a la Junta de Gobierno, a través de su Presidente, las opiniones que tuvieren sobre el proyecto de Programa Anual de Estadística y Geografía;</p><p>II. Apoyar en la supervisión de la ejecución del programa anual a que se refiere la fracción anterior;</p><p>III. Revisar los proyectos de indicadores y normas técnicas que las Unidades sometan a su consideración;</p><p>IV. Proponer a la Junta de Gobierno, en tiempo y forma a través de su Presidente, las normas técnicas, así como los indicadores y la información que deba considerarse Información de Interés Nacional, de la materia que corresponda tomando en cuenta los estándares nacionales e internacionales, así como las mejores prácticas en la materia;</p><p>V. Presentar a la Junta de Gobierno un informe anual sobre sus actividades;</p><p>VI. Proponer al Instituto, en tiempo y forma, aquéllas metodologías utilizadas para generar la información, tomando en cuenta los estándares nacionales e internacionales, así como las mejores prácticas en la materia, las que serán revisadas por organismos internacionales periódicamente al menos cada ocho años, y</p><p>VII. Opinar respecto de los demás asuntos que someta a su consideración la Junta de Gobierno.</p><p>Las decisiones de los Comités Ejecutivos se tomarán por mayoría, en caso de empate tendrá voto de calidad aquélla Unidad que, en el ámbito de su competencia, haya sometido la propuesta a votación.</p>','ordinario',30,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('63f8c757-fc38-5dcf-95ab-005b068f997f'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 31','<p>ARTÍCULO 31.- Los Comités Técnicos Especializados serán instancias colegiadas de participación y consulta creados por acuerdo de la Junta de Gobierno, integrados por representantes de las Unidades y del Instituto, quien promoverá la constitución y adecuado funcionamiento de los mismos sujetándose a las disposiciones siguientes:</p><p>I. Podrán ser temáticos, regionales o especiales, permanentes o temporales;</p><p>II. Se integrarán por las Unidades que, a propuesta del Presidente o del vicepresidente encargado del Subsistema Nacional de Información que corresponda, la Junta de Gobierno determine invitar a participar como miembros, y</p><p>III. Podrán asistir a ellos como invitados, los representantes de las instituciones sociales y privadas que el propio Comité determine.</p><p>El Instituto nombrará al servidor público -del propio Instituto- que fungirá como secretario técnico de los comités que se constituyan con base en este artículo.</p><p>Los integrantes de los Comités Técnicos Especializados desempeñarán sus funciones en dichos órganos colegiados de manera honoraria.</p>','ordinario',31,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('3e1e6696-a053-543c-bc9a-308329329030'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 32','<p>ARTÍCULO 32.- Los Comités Técnicos Especializados a los que se refiere el artículo anterior tendrán las funciones siguientes:</p><p>I. Promover entre los coordinadores de las Unidades, el conocimiento y aplicación de las normas técnicas y disposiciones de carácter general que expida el Instituto;</p><p>II. Coadyuvar en la elaboración o revisión de las normas técnicas;</p><p>III. Colaborar en los asuntos de su competencia a solicitud del Instituto;</p><p>IV. Presentar a la Junta de Gobierno un informe anual sobre sus actividades, y</p><p>V. Prestar a los Subsistemas el apoyo que proceda en términos del acuerdo de creación del Comité Técnico Especializado de que se trate.</p><p>SECCIÓN V De las Unidades del Estado</p>','ordinario',32,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('43b5bc26-2617-5168-ab8b-535ae635d1c1'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 33','<p>ARTÍCULO 33.- Las Unidades del Estado distintas al Instituto, cuando desarrollen actividades relacionadas con la producción, integración, conservación y difusión de Información de Interés Nacional, deberán:</p><p>I. Observar las bases, normas y principios que el Instituto, a propuesta de los Comités Ejecutivos de los Subsistemas, establezca y dé a conocer para producir, integrar y difundir Información;</p><p>II. Colaborar en la integración del catálogo nacional de indicadores a que se refiere el artículo 56 de esta Ley;</p><p>III. Elaborar, sujetándose a las disposiciones aplicables y a las disponibilidades presupuestarias, los anteproyectos de presupuestos anuales de los trabajos estadísticos y geográficos de su competencia, en concordancia con los programas a que se refiere el artículo 9 de esta Ley;</p><p>IV. Proponer, en tiempo y forma, al Comité Ejecutivo que corresponda, los proyectos de normas técnicas y metodologías que, en el ámbito de sus funciones, sean necesarias para la realización de las Actividades tomando en cuenta los estándares nacionales e internacionales y las mejores prácticas en la materia; así como los temas, información o indicadores que deban someterse a consideración de la Junta de Gobierno para efectos de la fracción II del artículo 77 de esta Ley;</p><p>V. Proporcionar al Instituto, directamente o a través de su coordinador, la Información que éste le solicite;</p><p>VI. Resguardar y conservar la Información, así como los metadatos o especificaciones concretas de la aplicación de las metodologías que hubieren utilizado en la elaboración de la misma, en la forma y términos que, previo acuerdo con el coordinador de la Unidad que corresponda, señale el Instituto, y</p><p>VII. Realizar las demás actividades que sean necesarias para el cumplimiento de las previsiones anteriores.</p><p>Cuando por mandato legal las Unidades estén facultadas para producir y dar a conocer Información Estadística y Geográfica deberán observar lo que al respecto determine la ley correspondiente, sin perjuicio de que apliquen, en lo conducente, lo señalado en la fracción I de este artículo.</p><p>El Banco de México determinará las normas relativas a la información que produzca y requiera, para la conducción de la política monetaria.</p>','ordinario',33,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('c0ffb902-c2c2-534c-a581-a1a39c240ab5'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 34','<p>ARTÍCULO 34.- Para el correcto funcionamiento y coordinación del Sistema, se designará a un coordinador por cada grupo de Unidades correspondientes a una misma cámara legislativa federal o local; dependencia o entidad paraestatal de la administración pública federal; entidad federativa; organismo constitucional autónomo federal o de las entidades federativas, municipio o tribunal administrativo, así como del Poder Judicial de la Federación o de los tribunales superiores de justicia de las entidades federativas.</p><p>Las designaciones deberán recaer en personas que ocupen, al menos, el nivel de titular de unidad o su equivalente, o el nivel inmediato inferior al de aquélla a la que corresponda hacer el nombramiento y que preferentemente cuenten con conocimientos y experiencia en materia de Información. Cada coordinador deberá nombrar a su suplente quien deberá ocupar el nivel inmediato inferior a aquél.</p>','ordinario',34,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('9f901fd6-79cd-5c03-8298-18e3fde050b4'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 35','<p>ARTÍCULO 35.- Los coordinadores a que se refiere el artículo anterior tendrán bajo su responsabilidad:</p><p>I. Ser el enlace del grupo de Unidades que corresponda con el Instituto;</p><p>II. Participar en los Comités de los Subsistemas en términos de la presente Ley;</p><p>III. Dar a conocer a las Unidades que coordinen, los acuerdos alcanzados en los Comités en los que participen, así como apoyar a los Comités de los Subsistemas en la supervisión de su ejecución y cumplimiento;</p><p>IV. Solicitar a las Unidades que coordinen la integración de la Información que solicite el Instituto;</p><p>V. Promover el cumplimiento y aplicación de las normas técnicas y disposiciones de carácter general que expida el Instituto, y</p><p>VI. Proponer al Comité Ejecutivo respectivo los indicadores y normas técnicas de las Unidades que coordinen.</p>','ordinario',35,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('ca9bcfed-5a5c-5f60-a015-621b3cb25688'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 36','<p>ARTÍCULO 36.- A efecto de apoyar en la capacitación y actualización de los servidores públicos de las Unidades, así como en la investigación permanente en temas de producción y análisis de la Información, el Instituto podrá realizar las funciones siguientes:</p><p>I. Elaborar un programa permanente y actualizado, de formación y perfeccionamiento de las capacidades técnicas de los servidores públicos de las Unidades, así como un programa de investigación permanente en temas de producción y análisis de la Información, para atender las necesidades de las Unidades;</p><p>II. Realizar estudios relativos al Sistema;</p><p>III. Realizar investigaciones sobre nuevas metodologías para la producción y difusión de Información;</p><p>IV. Analizar y adecuar al ámbito nacional, las recomendaciones que emitan los organismos internacionales para la generación de Información;</p><p>V. Actuar como consultor técnico de las Unidades del Estado;</p><p>VI. Realizar estudios permanentes de la legislación en materia estadística y geográfica vigente en cada una de las entidades federativas, así como de derecho comparado, y</p><p>VII. Capacitar a los servidores públicos de las Unidades del Estado.</p><p>De los Informantes del Sistema</p><p>SECCIÓN I De los Derechos y Obligaciones de los Informantes del Sistema</p>','ordinario',36,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('7410e9fd-efdf-5599-84f3-327ecc956036'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 37','<p>ARTÍCULO 37.- Los datos que proporcionen para fines estadísticos los Informantes del Sistema a las Unidades en términos de la presente Ley, serán estrictamente confidenciales y bajo ninguna circunstancia podrán utilizarse para otro fin que no sea el estadístico.</p><p>El Instituto no deberá proporcionar a persona alguna, los datos a que se refiere este artículo para fines fiscales, judiciales, administrativos o de cualquier otra índole.</p>','ordinario',37,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('2bf2a227-bda1-53f5-9c65-f5a5e62cfd02'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 38','<p>ARTÍCULO 38.- Los datos e informes que los Informantes del Sistema proporcionen para fines estadísticos y que provengan de registros administrativos, serán manejados observando los principios de confidencialidad y reserva, por lo que no podrán divulgarse en ningún caso en forma nominativa o individualizada, ni harán prueba ante autoridad judicial o administrativa, incluyendo la fiscal, en juicio o fuera de él.</p><p>Cuando se deba divulgar la información a que se refiere el párrafo anterior, ésta deberá estar agregada de tal manera que no se pueda identificar a los Informantes del Sistema y, en general, a las personas físicas o morales objeto de la información.</p><p>El Instituto expedirá las normas que aseguren la correcta difusión y el acceso del público a la Información, con apego a lo dispuesto en este artículo.</p>','ordinario',38,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('b2bf17cf-bfad-5bb6-be98-064c265c1f5f'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 39','<p>ARTÍCULO 39.- El Instituto realizará las acciones tendientes a lograr, que los Informantes del Sistema incurran en los menores costos posibles en la entrega de la información que les solicite.</p>','ordinario',39,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('ff9d0571-1351-5d52-99cb-13792ede3a0a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 40','<p>ARTÍCULO 40.- Los Informantes del Sistema a quienes se les requieran datos estadísticos o geográficos, deberán ser enterados de:</p><p>I. El carácter obligatorio o potestativo de sus respuestas, según corresponda;</p><p>II. La obligación de proporcionar respuestas veraces, y de las consecuencias de la falsedad en sus respuestas a los cuestionarios que se les apliquen;</p><p>III. La posibilidad del ejercicio del derecho de rectificación;</p><p>IV. La confidencialidad en la administración, manejo y difusión de sus datos;</p><p>V. La forma en que será divulgada o suministrada la Información, y</p><p>VI. El plazo para proporcionar los datos, el cual deberá fijarse conforme a la naturaleza y características de la información a rendir.</p><p>Las anteriores previsiones deberán aparecer en los cuestionarios y documentos que se utilicen para recopilar datos estadísticos o geográficos.</p>','ordinario',40,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('f4c41fbb-ec5e-547c-a0e2-d713b663abae'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 41','<p>ARTÍCULO 41.- Los Informantes del Sistema, en su caso, podrán exigir que sean rectificados los datos que les conciernan, para lo cual deberán demostrar que son inexactos, incompletos o equívocos.</p><p>Cuando proceda, deberá entregarse al Informante del Sistema, un documento en donde se certifique el registro de la modificación o corrección. Las solicitudes correspondientes se presentarán ante la misma autoridad que captó la información.</p>','ordinario',41,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('b35642b2-03ba-57a2-822e-2d614e38a1a9'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 42','<p>ARTÍCULO 42.- Los Informantes del Sistema podrán denunciar ante las autoridades administrativas y judiciales, todo hecho o circunstancia del que se derive que se hubieren desconocido los principios de confidencialidad y reserva a que se refiere esta Ley.</p>','ordinario',42,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('be192f45-ce2d-5695-a26f-199b502cef44'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 43','<p>ARTÍCULO 43.- La información que sea obtenida mediante engaño o cualquier otro medio ilícito carecerá de validez. Los Informantes del Sistema de quienes bajo estas circunstancias se hubiere obtenido tal información, independientemente del ejercicio de las acciones penales y administrativas que fueren procedentes, podrán comunicar dicha circunstancia al Instituto. Lo anterior, sin perjuicio de que el interesado proporcione a las Unidades, en los términos de esta Ley, la información correspondiente.</p>','ordinario',43,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('d6d87218-c503-5587-83d0-5b88467875c7'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 44','<p>ARTÍCULO 44.- El Instituto, cuando no cuente con otros medios técnicos de comprobación o validación de la información proporcionada por los Informantes del Sistema, podrá realizar inspecciones de verificación en los términos de la Sección III de este Capítulo, en las cuales podrá solicitar la exhibición de documentos que acrediten los datos estrictamente estadísticos y geográficos.</p><p>Las Unidades que no cuenten con un procedimiento similar establecido en algún ordenamiento jurídico, podrán realizar las inspecciones de verificación a que se refiere el párrafo anterior.</p><p>Cuando los datos consignados en la documentación elaborada para captarlos no se encuentren en los documentos exhibidos, deberá señalarse la fuente o presentarse los antecedentes que hubieran servido de base para la información suministrada.</p>','ordinario',44,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('6396ab3d-6529-54fa-9bca-8c98f4480721'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 45','<p>ARTÍCULO 45.- Los Informantes del Sistema estarán obligados a proporcionar, con veracidad y oportunidad, los datos e informes que les soliciten las autoridades competentes para fines estadísticos, censales y geográficos, y prestarán apoyo a las mismas.</p><p>La participación y colaboración de los habitantes de la República en el levantamiento de los censos, será obligatoria y gratuita en los términos señalados en el artículo 5o. de la Constitución Política de los Estados Unidos Mexicanos.</p><p>Los propietarios, poseedores o usufructuarios de predios ubicados en el territorio nacional, prestarán apoyo en los trabajos de campo que realicen las autoridades para captar Información.</p>','ordinario',45,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('218a531f-e253-573f-b229-8f5091287efe'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 46','<p>ARTÍCULO 46.- Las Unidades estarán obligadas a respetar la confidencialidad y reserva de los datos que para fines estadísticos proporcionen los Informantes del Sistema. Los servidores públicos de la Federación, de las entidades federativas, de los municipios y de las demarcaciones territoriales de la Ciudad de México, tendrán la obligación de proporcionar la información básica que hubieren obtenido en el ejercicio de sus funciones y sirva para generar Información de Interés Nacional, que les solicite el Instituto en los términos de la presente Ley. Lo anterior, con excepción de los secretos bancario,</p><p>fiduciario y bursátil, no será violatorio de la confidencialidad o reserva que se establezca en otras disposiciones. Párrafo reformado DOF 19-01-2018</p><p>El registro o recolección de los datos que, en cumplimiento de esta Ley, deban proporcionar los Informantes del Sistema, no prejuzga sobre los derechos de propiedad intelectual, industrial o de otro tipo que se originen en los trabajos de investigación científica de carácter estadístico, geográfico o de otra materia, que los mencionados Informantes del Sistema realicen y que son regulados por la legislación respectiva.</p>','ordinario',46,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('37d0ee0a-43ce-5eea-8da1-1139a8516c97'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 47','<p>ARTÍCULO 47.- Los datos que proporcionen los Informantes del Sistema, serán confidenciales en términos de esta Ley y de las reglas generales que conforme a ella dicte el Instituto.</p><p>La Información no queda sujeta a la Ley Federal de Transparencia y Acceso a la Información Pública Gubernamental, sino que se dará a conocer y se conservará en los términos previstos en la presente Ley.</p><p>Sin perjuicio de lo señalado en el párrafo anterior, el Instituto, respecto de la información correspondiente a su gestión administrativa, quedará sujeto a lo dispuesto en la Ley Federal de Transparencia y Acceso a la Información Pública Gubernamental.</p><p>SECCIÓN II De las Inspecciones a los Informantes del Sistema</p>','ordinario',47,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('df55d17e-e46d-54df-922d-95c1fc50198c'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 48','<p>ARTÍCULO 48.- El Instituto, en el ejercicio de las facultades que le confiere esta Ley, podrá efectuar inspecciones para verificar la autenticidad de la Información, cuando los datos proporcionados sean incongruentes, incompletos o inconsistentes.</p>','ordinario',48,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('42b84c68-6b2d-5a44-9fe6-bce17bb70e89'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 49','<p>ARTÍCULO 49.- Las inspecciones de verificación a que se refiere el artículo anterior, se sujetarán a lo siguiente:</p><p>I. Se practicarán por orden escrita que expresará:</p><p>a) El fundamento y motivo de su realización;</p><p>b) El nombre del Informante del Sistema con quien se desahogará la diligencia, así como el lugar donde deberá efectuarse.</p><p>En el caso de que se ignore el nombre de la persona a que se refiere este inciso, se señalarán datos suficientes para su identificación;</p><p>c) El nombre de la o las personas que practicarán la diligencia, las cuales podrán ser sustituidas, debiendo notificar de tal hecho al Informante del Sistema, y</p><p>d) La Información objeto de verificación, así como la documentación que el Informante del Sistema deberá exhibir en la diligencia;</p><p>II. La diligencia se entenderá con la persona a que se refiere el inciso b) de la fracción I de este artículo, con quien la supla en su ausencia o con su representante legal, en su caso, y</p><p>III. La persona con quien se entienda la diligencia en términos de la fracción anterior, será requerida para que nombre a dos testigos y en caso de negativa serán designados por el personal que practique la diligencia, quien hará constar en el acta, en forma circunstanciada, los hechos y omisiones observados.</p><p>La persona con quien se entienda la diligencia, los testigos y el o los inspectores, firmarán el acta. Si los primeros o los testigos se niegan a firmar, así lo hará constar el o los inspectores, sin que esta circunstancia afecte el valor probatorio del acta. Un ejemplar del acta se entregará en todo caso a la persona con quien se entienda la diligencia.</p>','ordinario',49,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('7aeb9a42-3afa-5aea-a9f4-b0f9ae51ed43'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 50','<p>ARTÍCULO 50.- Los Informantes del Sistema, respecto de quienes se hubiesen practicado los actos a que se refiere el artículo anterior, podrán inconformarse con los hechos asentados en el acta correspondiente, mediante la interposición del recurso de revisión a que se refiere el Capítulo II del Título Cuarto de esta Ley.</p><p>SECCIÓN III De la Atención a las Solicitudes Oficiales de Información Provenientes del Extranjero</p>','ordinario',50,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('e1c96cef-d7e1-5a9a-81e2-5cd72e1ad5f3'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 51','<p>ARTÍCULO 51.- Las solicitudes de Información de Interés Nacional, que formulen gobiernos extranjeros u organismos y agencias internacionales, a las dependencias y entidades de la Administración Pública Federal, al Poder Judicial de la Federación, al Poder Legislativo Federal, a organismos constitucionales autónomos, a los poderes Ejecutivo, Legislativo y Judicial de las entidades federativas, a organizaciones o agrupaciones de los sectores social o privado o a particulares, deberán ser atendidas en términos de las disposiciones aplicables, directamente por la autoridad, organización, agrupación o particular de que se trate y hacerse del conocimiento del Instituto.</p><p>TÍTULO TERCERO DE LA ORGANIZACIÓN Y FUNCIONAMIENTO DEL INSTITUTO</p><p>Del Instituto Nacional de Estadística y Geografía</p>','ordinario',51,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('0eb378d1-9b4e-5768-8e1a-ad4f298f1739'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 52','<p>ARTÍCULO 52.- El Instituto es, conforme a lo dispuesto en el apartado B del artículo 26 de la Constitución Política de los Estados Unidos Mexicanos, un organismo público con autonomía técnica y de gestión, personalidad jurídica y patrimonio propios, responsable de normar y coordinar el Sistema Nacional de Información Estadística y Geográfica, así como de realizar las Actividades a que se refiere el artículo 59 de esta Ley.</p>','ordinario',52,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('c8768556-246f-5256-8b14-33a392d57c87'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 53','<p>ARTÍCULO 53.- El Instituto tendrá como objetivo prioritario, realizar las acciones tendientes a lograr que la Información de Interés Nacional se sujete a los principios enunciados en el artículo 3 de esta Ley.</p>','ordinario',53,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('56a794cb-c21f-5f14-a293-5d38a115f402'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 54','<p>ARTÍCULO 54.- El Instituto, conforme a los principios constitucionales que rigen al Sistema, realizará las acciones tendientes a lograr:</p><p>I. La adecuación conceptual de la Información de Interés Nacional, a las necesidades que el desarrollo económico y social del país impongan;</p><p>II. Que la Información sea comparable en el tiempo y en el espacio, y</p><p>III. La adecuación de los procedimientos estadísticos y geográficos a estándares internacionales, para facilitar su comparación.</p><p>SECCIÓN I De las Funciones del Instituto</p>','ordinario',54,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('01b5eeaa-b481-59bb-b2b7-10c4f206d55e'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 55','<p>ARTÍCULO 55.- El Instituto, en su calidad de unidad central coordinadora del Sistema, tendrá las funciones siguientes:</p><p>I. Normar y coordinar el Sistema, así como fomentar las acciones que permitan mantener su operación eficiente;</p><p>II. Normar y coordinar las Actividades que lleven a cabo las Unidades, tomando en cuenta los estándares nacionales e internacionales, así como las mejores prácticas en la materia;</p><p>III. Solicitar a las Unidades información relativa a sus Actividades, para la integración de los anteproyectos de los programas a los que hace referencia el artículo 9 de esta Ley;</p><p>IV. Solicitar a las Unidades la Información que éstas hayan obtenido en el ámbito de sus respectivas competencias y sea necesaria para el Sistema, y</p><p>V. Las demás que le correspondan conforme a esta Ley.</p>','ordinario',55,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('61a2fb95-2a33-5a3f-bc70-77db578d0bde'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 56','<p>ARTÍCULO 56.- El Instituto establecerá en coordinación con las Unidades, un catálogo nacional de indicadores, ajustándose a lo dispuesto en los artículos 22, 25 y 28 de esta Ley.</p>','ordinario',56,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('d1e50bc2-38dd-5a8a-b62a-4b5e08a66f54'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 57','<p>ARTÍCULO 57.- El Instituto deberá elaborar y someter a consideración del Comité Ejecutivo correspondiente, las normas técnicas y las metodologías que sean necesarias para realizar las Actividades Estadísticas y Geográficas de alguna materia o sector, cuando la Unidad que corresponda no las proponga oportunamente o estas no tomen en cuenta los estándares nacionales e internacionales o, en su caso, las mejores prácticas en la materia.</p>','ordinario',57,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('cc44a1aa-5c71-5431-9b5c-753fba554c6b'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 58','<p>ARTÍCULO 58.- El Instituto regulará, mediante la expedición de disposiciones de carácter general, la captación, procesamiento y publicación de la Información, para el debido funcionamiento del Sistema o autorizará las que utilicen las Unidades para tales efectos.</p><p>El Instituto vigilará el cumplimiento de las disposiciones de carácter general a que se refiere el párrafo anterior.</p><p>Con el objeto de garantizar la homogeneidad y comparación de la Información, el Instituto deberá proveer y promover el uso de definiciones, clasificaciones, nomenclaturas, abreviaturas, identificadores, directorios, símbolos, delimitaciones geográficas y demás elementos que a estos fines sean indispensables desde la captación y procesamiento de la información, hasta la etapa de su presentación y publicación.</p>','ordinario',58,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('533a1132-6546-55d5-a79b-99b96d75f004'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 59','<p>ARTÍCULO 59.- El Instituto tendrá las siguientes facultades exclusivas:</p><p>I. Realizar los censos nacionales;</p><p>II. Integrar el sistema de cuentas nacionales, y</p><p>III. Elaborar los índices nacionales de precios siguientes:</p><p>a. Índice Nacional de Precios al Consumidor, e</p><p>b. Índice Nacional de Precios Productor.</p><p>Las denominaciones censo nacional o cuentas nacionales no podrán ser empleadas en el nombre ni en la propaganda de registros, encuestas o enumeraciones distintas a las que practique el Instituto.</p><p>Cualquier contravención a lo dispuesto en este párrafo se sancionará en términos de lo dispuesto en el Título Cuarto de esta Ley.</p><p>El Instituto podrá producir cualquier otra Información de Interés Nacional cuando así lo determine la Junta de Gobierno, sujeto a la disponibilidad presupuestaria con la que cuente, conforme a lo señalado en el último párrafo del artículo 83 de esta Ley.</p>','ordinario',59,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('5afd7c04-9cee-5d91-9916-1e1cdc30b25e'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 60','<p>ARTÍCULO 60.- Sólo con la autorización del Instituto y previa opinión favorable de las autoridades competentes, las personas físicas o morales nacionales podrán captar fotografías aéreas con cámaras métricas o de reconocimiento y de otras imágenes por percepción remota dentro del espacio aéreo nacional, debiendo entregar al Instituto un informe detallado de los trabajos que hubieren realizado, así como una copia de los mismos cuando éste último se los requiera.</p>','ordinario',60,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('a49b7f9f-b084-5723-bac7-e72ee03b14ef'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 61','<p>ARTÍCULO 61.- Las personas físicas y morales extranjeras requerirán autorización del Instituto para efectuar actividades tendientes a:</p><p>I. Captar fotografías aéreas con cámaras métricas o de reconocimiento y de otras imágenes por percepción remota dentro del espacio aéreo nacional, y</p><p>II. Levantar información estadística y geográfica.</p><p>Las personas físicas o morales extranjeras que reciban la autorización a que se refiere este artículo, deberán proporcionar un informe detallado de los trabajos señalados en las fracciones anteriores, así como copia de las fotografías, imágenes e información correspondientes.</p><p>El otorgamiento de las autorizaciones de que trata este artículo, quedará condicionado a la obtención de opinión favorable de las autoridades competentes y a que se garantice, a satisfacción del propio Instituto, la entrega del informe y de las copias a que se refiere el párrafo anterior. El Instituto recabará la opinión de las autoridades competentes y resolverá lo conducente dentro de un plazo que no excederá de 30 días hábiles.</p>','ordinario',61,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('ba145094-8281-5de7-8b69-f8a445a96fb1'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 62','<p>ARTÍCULO 62.- El Instituto promoverá la adopción de métodos y normas técnicas en la captación de los datos objeto de registro, en coordinación con las autoridades a las que competa administrar directorios de personas físicas o morales, catastros, registros públicos de la propiedad y del comercio, padrones, inventarios y demás registros administrativos que permitan obtener Información.</p>','ordinario',62,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('833bbc78-0a57-5998-bcdd-a43f04e9792d'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 63','<p>ARTÍCULO 63.- Para el desarrollo de las Actividades Estadísticas y Geográficas colaborarán con el Instituto:</p><p>I. Los poderes Ejecutivo, Legislativo y Judicial de la Federación y de las entidades federativas;</p><p>II. Los organismos constitucionales autónomos;</p><p>III. Las autoridades municipales y de las demarcaciones territoriales de la Ciudad de México; Fracción reformada DOF 19-01-2018</p><p>IV. Las Unidades del Estado;</p><p>V. Las instituciones, agrupaciones u organizaciones sociales y privadas, y</p><p>VI. Los particulares.</p>','ordinario',63,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('85570602-26b6-58e2-b77c-37c2ec1bbcd2'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 64','<p>ARTÍCULO 64.- Previo cumplimiento de las formalidades legales y administrativas correspondientes y acuerdo favorable de su Junta de Gobierno, el Instituto deberá brindar el apoyo que le soliciten:</p><p>I. El Ejecutivo Federal y el Senado de la República en materia de tratados, convenios o acuerdos internacionales, cuando se establezcan derechos y obligaciones en materia de Información, así como aquellos que versen sobre límites del territorio nacional, y</p><p>II. El Ejecutivo Federal en caso de que se requiera Información para prevenir y, en su caso, atender emergencias o catástrofes originadas por desastres naturales.</p>','ordinario',64,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('f467e1f2-ece6-5ee9-bce9-555138e82ff3'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 65','<p>ARTÍCULO 65.- Previo cumplimiento de las formalidades legales y administrativas correspondientes y del acuerdo favorable de su Junta de Gobierno, el Instituto podrá brindar el apoyo que le soliciten:</p><p>I. Los poderes Legislativo y Judicial federales y legislativos de las entidades federativas, en la definición de límites de las entidades federativas, los municipios y las demarcaciones territoriales de la Ciudad de México, así como asesorar y apoyar a esos poderes en la identificación física de tales límites; Fracción reformada DOF 19-01-2018</p><p>II. El Congreso de la Unión, los gobiernos de las entidades federativas, así como las autoridades competentes para el levantamiento geodésico y para realizar el registro de los límites territoriales, conforme a las disposiciones aplicables, y Fracción reformada DOF 19-01-2018</p><p>III. Las autoridades locales, para la organización de los catastros de los municipios y para la realización del levantamiento geodésico de los límites aceptados o reconocidos de los estados.</p><p>SECCIÓN II De la Administración del Instituto</p>','ordinario',65,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('92ab5a0a-3bcf-5faf-b821-10982d227910'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 66','<p>ARTÍCULO 66.- El ejercicio de las funciones del Instituto corresponde, en el ámbito de sus respectivas competencias, a la Junta de Gobierno y al Presidente del Instituto.</p>','ordinario',66,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('941456ce-260a-5e68-958b-5e3e874fa00c'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 67','<p>ARTÍCULO 67.- La Junta de Gobierno es el órgano superior de dirección del Instituto, y estará integrada por cinco miembros designados por el Presidente de la República con la aprobación de la Cámara de Senadores o, en los recesos de esta última, de la Comisión Permanente.</p><p>De entre los miembros de la Junta de Gobierno, el Ejecutivo Federal nombrará al Presidente del Instituto, quien presidirá el citado órgano colegiado. El resto de los miembros de la Junta de Gobierno actuarán como vicepresidentes de la misma.</p>','ordinario',67,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('3c6e44de-2767-559f-886e-fc2d85030fd7'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 68','<p>ARTÍCULO 68.- La Presidencia será el órgano superior ejecutivo del Instituto. El Presidente del Instituto durará en su cargo seis años y los vicepresidentes de la Junta de Gobierno ocho años. El periodo del Presidente del Instituto comenzará el primero de enero del cuarto año calendario del periodo correspondiente al Presidente de la República. Los periodos de los vicepresidentes de la Junta de Gobierno serán escalonados, sucediéndose cada dos años e iniciándose el primero de enero del primer, tercer y quinto año del periodo del Ejecutivo Federal.</p><p>Los miembros de la Junta de Gobierno podrán ser designados para ocupar el cargo hasta por dos ocasiones.</p><p>Los miembros de la Junta de Gobierno ocuparán sus cargos sólo durante el tiempo por el cual hayan sido designados.</p>','ordinario',68,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('b721213b-34f1-5b77-9bd8-af33a4e97432'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 69','<p>ARTÍCULO 69.- La designación de los miembros de la Junta de Gobierno deberá recaer en personas que reúnan los requisitos siguientes:</p><p>I. Ser ciudadano mexicano por nacimiento, estar en pleno goce de sus derechos civiles y políticos, y no tener más de setenta años cumplidos a la fecha en que la designación sea entregada al Senado de la República o, en su caso, a la Comisión Permanente, para su ratificación;</p><p>II. Ser profesional distinguido en materias relacionadas con la estadística, la geografía o la economía, así como haber ocupado, por lo menos durante cinco años, algún cargo de alto nivel en los sectores público o privado, o ser un académico de reconocido prestigio en las materias mencionadas, y</p><p>III. No haber sido sentenciado por delitos intencionales, inhabilitado para ejercer el comercio o para desempeñar un empleo, cargo o comisión en el servicio público, ni removido de algún cargo del sector público o privado.</p>','ordinario',69,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('3c6f8dc4-33ac-5ae7-ab43-7c478362e06b'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 70','<p>ARTÍCULO 70.- Los miembros de la Junta de Gobierno no podrán desempeñar ningún otro empleo, cargo o comisión, con excepción de actividades docentes, científicas, culturales o de beneficencia, no remuneradas.</p>','ordinario',70,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('55ccd564-e3f2-5be2-a49f-b74105b5da74'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 71','<p>ARTÍCULO 71.- Las vacantes que se produzcan en la Junta de Gobierno serán cubiertas por el nuevo miembro que se designe para integrarla. En caso de vacante en el puesto de Presidente del Instituto, el Ejecutivo Federal podrá nombrar para ocupar tal cargo a un miembro de la Junta de Gobierno en funciones, o bien, designar a un nuevo miembro de la Junta de Gobierno y, ya integrada ésta, nombrar de entre sus cinco miembros al Presidente del Instituto.</p><p>En tanto se hace el nombramiento de Presidente, el miembro de la Junta de Gobierno con mayor antigüedad en el cargo será presidente interino del Instituto y presidirá la Junta de Gobierno. En caso de que hubiere dos o más miembros con igual antigüedad, la propia Junta de Gobierno elegirá de entre ellos al presidente interino a más tardar en la siguiente sesión de dicho órgano colegiado y, de no llegar a un acuerdo, la designación se realizará por el Presidente de la República.</p><p>Los miembros que cubran vacantes que se produzcan antes de la terminación del periodo respectivo, durarán en su cargo sólo por el tiempo que le faltare desempeñar al sustituido. Si al término que corresponde al Presidente del Instituto, se nombra a un miembro de la Junta de Gobierno en funciones para ocupar tal puesto, este nombramiento será por seis años independientemente del tiempo que hubiere sido miembro de la Junta de Gobierno.</p>','ordinario',71,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('45efea89-563f-5d47-9bed-18d090ae3f61'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 72','<p>ARTÍCULO 72.- Los miembros de la Junta de Gobierno se abstendrán de participar con la representación del Instituto en actos políticos, partidistas o religiosos.</p>','ordinario',72,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('1de3c92b-a678-5f28-8dce-0c9c7edb9d37'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 73','<p>ARTÍCULO 73.- Son causas de remoción de un miembro de la Junta de Gobierno:</p><p>I. La incapacidad física o mental que impida el correcto ejercicio de sus funciones por más de tres meses;</p><p>II. El desempeño de algún empleo, cargo o comisión, en contravención a lo dispuesto en el artículo 70 de esta Ley;</p><p>III. Dejar de reunir cualesquiera de los requisitos señalados en el artículo 69 anterior;</p><p>IV. Incumplir los acuerdos de la Junta de Gobierno o actuar deliberadamente en exceso o defecto de sus atribuciones;</p><p>V. Utilizar en beneficio propio o de terceros, la información confidencial o de otra naturaleza de que disponga en razón de su cargo, así como divulgar tal información en términos distintos a los autorizados por esta Ley;</p><p>VI. Someter a consideración de la Junta de Gobierno, a sabiendas, información falsa o alterada;</p><p>VII. Participar en actos políticos, partidistas o religiosos con la representación del Instituto;</p><p>VIII. No excusarse de participar en aquellas tomas de decisiones en las que sus intereses personales se encuentren en conflicto con los del Instituto, y</p><p>IX. Ausentarse de sus labores por más de tres días consecutivos, o por cinco días no consecutivos en el lapso de un mes, sin autorización de la Junta de Gobierno o sin mediar causa de fuerza mayor o motivo justificado.</p>','ordinario',73,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('831fe3c8-d0c3-5970-9770-31dd7b84e3de'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 74','<p>ARTÍCULO 74.- Compete a la Junta de Gobierno dictaminar sobre la existencia de las causas de remoción señaladas en el artículo inmediato anterior, debiendo hacerlo a solicitud del Presidente de la República o de cuando menos dos de sus miembros. El dictamen se formulará según resolución de la mayoría de los miembros de la Junta de Gobierno, después de conceder el derecho de audiencia al afectado y sin que éste participe en la votación.</p><p>El dictamen, con la documentación que lo sustente, incluida la argumentación por escrito que, en su caso, el afectado hubiere presentado, será enviado al Ejecutivo Federal para su resolución definitiva.</p>','ordinario',74,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('368a0e0a-db96-5835-9ff5-2b8094ddc166'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 75','<p>ARTÍCULO 75.- El Presidente del Instituto o cuando menos dos vicepresidentes, podrán convocar a reuniones de la Junta de Gobierno.</p><p>Las sesiones de la Junta de Gobierno deberán celebrarse con la asistencia de por lo menos tres de sus miembros. Si no concurriere el Presidente, la sesión será presidida por el miembro con mayor antigüedad. En caso de que hubiere dos o más miembros con igual antigüedad, los miembros asistentes elegirán de entre ellos al que deba presidir la sesión.</p><p>Las resoluciones de la Junta de Gobierno requerirán para su validez del voto aprobatorio de la mayoría de los miembros presentes, con excepción de las resoluciones a que se refiere el artículo 77, fracciones II, IV y V de esta Ley, para las cuales será necesario el voto favorable de la mayoría de los miembros de la Junta. La persona que presida la sesión tendrá voto de calidad en caso de empate.</p><p>La Junta de Gobierno podrá acordar la asistencia de servidores públicos del Instituto a sus sesiones, para que le rindan directamente la información que les solicite.</p><p>A las sesiones de la Junta de Gobierno podrán asistir los invitados que la propia Junta de Gobierno determine.</p><p>Las personas que asistan a las sesiones deberán guardar confidencialidad respecto de los asuntos que se traten en ellas, salvo autorización expresa de la Junta de Gobierno para hacer alguna comunicación.</p>','ordinario',75,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('269310e1-88f2-58f2-869f-2380a3c59ba6'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 76','<p>ARTÍCULO 76.- La remuneración y prestaciones que reciban los miembros de la Junta de Gobierno por el desempeño de su cargo, no serán mayores ni menores de las que correspondan al nivel de Subsecretario de la Administración Pública Federal. El Presidente de la Junta de Gobierno contará con</p><p>una remuneración 10% mayor a la que corresponda a los vicepresidentes de la Junta de Gobierno, dentro del nivel antes señalado. Las remuneraciones y prestaciones que perciban el resto de los servidores públicos del Instituto, en ningún caso podrán exceder las previstas para los integrantes del mencionado órgano de gobierno.</p><p>Lo señalado en el párrafo anterior, se realizará sujetándose a los límites de los tabuladores de percepciones que establezca la Cámara de Diputados, al aprobar el Presupuesto de Egresos de la Federación para el ejercicio fiscal correspondiente.</p><p>Las relaciones laborales de los trabajadores del Instituto, se sujetarán a lo dispuesto en el apartado B del artículo 123 de la Constitución Política de los Estados Unidos Mexicanos.</p><p>SECCIÓN III De las Atribuciones de la Junta de Gobierno</p>','ordinario',76,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('04db8d80-b776-586e-8e3a-160d665f9006'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 77','<p>ARTÍCULO 77.- Corresponderá a la Junta de Gobierno, como órgano superior de dirección del Instituto, el despacho de los asuntos siguientes:</p><p>I. Aprobar los programas a que se refiere el artículo 9 de esta Ley;</p><p>II. Determinar la Información que se considerará de Interés Nacional de conformidad con lo dispuesto en el artículo 78 de la presente Ley;</p><p>III. Determinar la Información que deba ser producida por el Instituto en los términos del último párrafo del artículo 59 de esta Ley;</p><p>IV. Determinar la Información que deba ser de divulgación restringida por motivos de seguridad nacional;</p><p>V. Determinar, atendiendo a las necesidades del Sistema, la creación de otros Subsistemas en términos de lo dispuesto en el último párrafo del artículo 17 de esta Ley;</p><p>VI. Determinar qué Unidades serán invitadas, como miembros de los Comités Técnicos Especializados a los que se hace referencia en la fracción II del artículo 31 de esta Ley;</p><p>VII. Aprobar los indicadores generados por los Subsistemas;</p><p>VIII. Normar el funcionamiento del Sistema y regular la captación, procesamiento y publicación de la Información que se genere, con base en los dictámenes que, en su caso, emita el Comité Ejecutivo correspondiente;</p><p>IX. Aprobar el Reglamento Interior del Instituto;</p><p>X. Aprobar el programa anual de trabajo del Instituto, el cual deberá elaborarse con base en el Programa Anual de Estadística y Geografía previsto en la fracción III del artículo 9 de esta Ley; el anteproyecto de presupuesto anual; el establecimiento y cierre de oficinas regionales y otras instalaciones u oficinas con base en su disponibilidad presupuestaria; así como el nombramiento y remoción de los servidores públicos que ocupen los dos niveles jerárquicos inferiores al de miembro de la Junta de Gobierno;</p><p>XI. Aprobar al final de cada año, el calendario que contenga las fechas de publicación de Información de Interés Nacional a que habrá de sujetarse el Instituto, en el año inmediato siguiente;</p><p>XII. Expedir los lineamientos generales, otorgar las autorizaciones y establecer los registros a que se refieren los artículos 58, 60 y 61 y los artículos 93 y 95 de esta Ley, respectivamente;</p><p>XIII. Aprobar la imposición de sanciones administrativas por infracciones a la presente Ley. Dicha facultad podrá delegarse en el Presidente o en otros servidores públicos del Instituto, considerando la naturaleza de la infracción o el monto de las multas;</p><p>XIV. Aprobar las políticas para la administración de los recursos humanos, financieros y materiales del Instituto, en términos de las disposiciones aplicables;</p><p>XV. Nombrar y remover a su secretario de actas, así como a su suplente, quienes deberán ser servidores públicos del Instituto;</p><p>XVI. Resolver sobre otros asuntos relacionados con la aplicación de esta Ley, que cualquiera de sus miembros sometan a su consideración, y</p><p>XVII. Las demás que resulten de esta Ley y de otras disposiciones legales aplicables.</p><p>Los asuntos a que se refieren las fracciones I, III, X y XIV del presente artículo, deberán aprobarse con base en las propuestas que presente al efecto el Presidente.</p><p>En aquellos casos en los que se deba recabar la opinión previa de los órganos colegiados a que se refiere la presente Ley, se deberán presentar a la Junta de Gobierno junto con la propuesta correspondiente, las mencionadas opiniones.</p>','ordinario',77,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('e0c4896c-578d-506f-ac16-2df78787c883'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 78','<p>ARTÍCULO 78.- Además de los temas señalados en las fracciones I a III del artículo 59 del presente ordenamiento, sólo podrá considerarse Información de Interés Nacional para efectos de esta Ley, la que satisfaga los cuatro criterios siguientes:</p><p>I. Se trate de los siguientes temas, grupos de datos o indicadores: población y dinámica demográfica; salud; educación; empleo; distribución de ingreso y pobreza; de gobierno, seguridad pública e impartición de justicia; vivienda; sistema de cuentas nacionales; información financiera; precios; trabajo; ciencia y tecnología; telecomunicaciones y radiodifusión; atmósfera; biodiversidad; agua; suelo; flora; fauna; residuos peligrosos y residuos sólidos; marco de referencia geodésico; límites costeros, internacionales, estatales y municipales; datos de relieve continental, insular y submarino; datos catastrales, topográficos, de recursos naturales y clima, y nombres geográficos, o bien se trate de temas que sean aprobados por unanimidad por el Consejo Consultivo Nacional, incluyendo aquéllos que deban conocer los Subsistemas a que se refiere el último párrafo del artículo 17 de este ordenamiento; Fracción reformada DOF 14-07-2014, 19-01-2018, 25-06-2018</p><p>II. Resulte necesaria para sustentar el diseño y la evaluación de las políticas públicas de alcance nacional;</p><p>III. Sea generada en forma regular y periódica, y</p><p>IV. Se elabore con base en una metodología científicamente sustentada.</p><p>Sin perjuicio de lo anterior, también podrá ser considerada como Información de Interés Nacional la que resulte necesaria para prevenir y, en su caso, atender emergencias o catástrofes originadas por desastres naturales, y aquélla que se deba generar en virtud de un compromiso establecido en algún tratado internacional.</p>','ordinario',78,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('45182cda-0c10-5575-af35-7787aae4c034'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 79','<p>ARTÍCULO 79.- Los miembros de la Junta de Gobierno tendrán la responsabilidad de procurar que las relaciones del Instituto con las Unidades del Estado y otros sectores relevantes para el trabajo del propio Instituto, se desarrollen en forma apropiada para conseguir los objetivos del Instituto y del Sistema.</p><p>Al efecto, estas tareas se dividirán en los cinco sectores siguientes: de información demográfica y social; de información económica y financiera; de información geográfica y del medio ambiente; de gobierno, seguridad pública e impartición de justicia y de relaciones con los sectores académico, privado e internacional. Párrafo reformado DOF 25-06-2018</p><p>SECCIÓN IV De las Atribuciones del Presidente del Instituto</p>','ordinario',79,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('1ac96bce-9e13-59cf-89f1-bc7dfcb6ff60'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 80','<p>ARTÍCULO 80.- Corresponden al Presidente del Instituto las atribuciones siguientes:</p><p>I. Tener a su cargo la administración del Instituto, la representación legal de éste, y el ejercicio de sus funciones, sin perjuicio de las atribuciones que la Ley confiere a la Junta de Gobierno;</p><p>II. Ejecutar los acuerdos de la Junta de Gobierno;</p><p>III. Someter a la consideración y, en su caso, aprobación de la Junta de Gobierno los asuntos mencionados en las fracciones I, III, X y XIV del artículo 77 de esta Ley. Tratándose de lo dispuesto en la fracción I del citado artículo 77, y antes de someter el asunto a la consideración de la Junta de Gobierno, en cumplimiento a lo dispuesto en el artículo 15 fracción I de este ordenamiento, el Presidente deberá consultar al Consejo Consultivo Nacional y a las demás instancias que procedan en términos de esta Ley;</p><p>IV. Dar a conocer a los Poderes de la Unión y al público en general el calendario de publicación de Información de Interés Nacional una vez aprobado por la Junta de Gobierno;</p><p>V. Aplicar las políticas para la administración de los recursos humanos, financieros y materiales del Instituto, de acuerdo a sus programas y objetivos, y</p><p>VI. Las demás que resulten de esta Ley y de otras disposiciones legales aplicables.</p><p>Para la mejor organización del trabajo, el Presidente del Instituto podrá, sin perjuicio de su ejercicio directo, delegar sus atribuciones en algún vicepresidente de la Junta de Gobierno o servidor público subalterno. Las atribuciones a que se refieren las fracciones III y IV de este artículo serán indelegables.</p><p>Las ausencias temporales del Presidente del Instituto serán suplidas en los términos señalados por el segundo párrafo del artículo 71 de esta Ley.</p>','ordinario',80,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('ab5b1bb9-85a6-5499-a9a8-d05ed5a8d6af'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 81','<p>ARTÍCULO 81.- El Presidente del Instituto tendrá la facultad de determinar el sector que, de entre los cuatro señalados en el artículo 79 de esta Ley, deberá atender y coordinar cada uno de los vicepresidentes de la Junta de Gobierno como parte de su labor ordinaria y cotidiana dentro del Instituto. Párrafo reformado DOF 27-01-2017</p><p>Al tomar las decisiones a que se refiere el párrafo anterior, el Presidente deberá tener en cuenta los antecedentes laborales y académicos de cada uno de los miembros de la Junta de Gobierno.</p><p>SECCIÓN V Del Patrimonio del Instituto</p>','ordinario',81,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('00a08324-c218-5bb8-bad6-25f809a39dea'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 82','<p>ARTÍCULO 82.- El patrimonio del Instituto se integra con:</p><p>I. Los bienes inmuebles o muebles que adquiera para el cumplimiento de su objeto, incluyendo los que la Federación haya destinado para tal fin o para su uso exclusivo;</p><p>II. Los recursos que anualmente apruebe para el Instituto la Cámara de Diputados del Congreso de la Unión, en el Presupuesto de Egresos de la Federación;</p><p>III. Las donaciones que reciba para el cumplimiento de su objeto, y</p><p>IV. Los ingresos que reciba por cualquier otro concepto, incluso los derivados de la aplicación de la presente Ley.</p><p>El Instituto no podrá tener más bienes inmuebles que los estrictamente necesarios para cumplir con su objeto.</p>','ordinario',82,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('abf3b169-938d-5453-bf2f-f17a3e9ddb3a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 83','<p>ARTÍCULO 83.- De conformidad con lo dispuesto en el artículo 5 de la Ley Federal de Presupuesto y Responsabilidad Hacendaria, para su tratamiento presupuestario el Instituto se sujetará a lo siguiente:</p><p>I. Aprobará su proyecto de presupuesto y deberá enviarlo a la Secretaría de Hacienda y Crédito Público para su integración al proyecto de Presupuesto de Egresos de la Federación, observando los criterios generales de política económica y los techos globales de gasto establecidos por el Ejecutivo Federal;</p><p>II. Ejercerá su presupuesto observando lo dispuesto en la Ley Federal de Presupuesto y Responsabilidad Hacendaria, sin sujetarse a las disposiciones generales emitidas por las Secretarías de Hacienda y Crédito Público y de la Función Pública. Dicho ejercicio deberá realizarse con base en los principios de eficiencia, eficacia y transparencia y estará sujeto a la evaluación y control de los órganos correspondientes;</p><p>III. Autorizará las adecuaciones a su presupuesto sin requerir la autorización de la Secretaría de Hacienda y Crédito Público, siempre y cuando no rebasen el techo global de su presupuesto aprobado;</p><p>IV. Realizará sus pagos a través de su tesorería;</p><p>V. Determinará los ajustes que correspondan en su presupuesto en caso de disminución de ingresos, observando en lo conducente lo dispuesto en el artículo 21 de la Ley Federal de Presupuesto y Responsabilidad Hacendaria, y</p><p>VI. Llevará la contabilidad y elaborará sus informes conforme a lo previsto en la Ley Federal de Presupuesto y Responsabilidad Hacendaria, y deberá enviarlos a la Secretaría de Hacienda y Crédito Público para su integración a los informes trimestrales y a la Cuenta Pública;</p><p>El Presupuesto de Egresos de la Federación del ejercicio fiscal en que deban realizarse los censos nacionales, las cuentas nacionales y los índices nacionales de precios, a que se refiere el artículo 59 de esta Ley, deberá contemplar los recursos suficientes para que el Instituto los lleve a cabo.</p><p>Las Actividades Estadísticas y Geográficas que, en adición a las señaladas en el párrafo anterior, el Instituto determine llevar a cabo en los términos de esta Ley, estarán sujetas a la disponibilidad presupuestaria que, en su caso, se apruebe para tales efectos en el Presupuesto de Egresos de la Federación.</p>','ordinario',83,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('8533f66c-1df7-55ba-8d5f-5ffb0a87bcc2'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 84','<p>ARTÍCULO 84.- El Instituto incorporará, en los términos de las disposiciones aplicables, como parte de su presupuesto los ingresos derivados de las cuotas por los servicios que preste por concepto de investigación, capacitación, elaboración de estadísticas especiales, estudios específicos o trabajos en materia de geografía, así como los que provengan de la venta de publicaciones, reproducciones y otros servicios. En los casos en que el Instituto preste los servicios señalados en colaboración con otras Unidades, incorporará en su presupuesto los ingresos que le correspondan al Instituto.</p>','ordinario',84,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('776d8f83-8b2d-52a1-bcbc-be3cfef4c224'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 85','<p>ARTÍCULO 85.- Los recursos que las dependencias y entidades de la Administración Pública Federal, el Poder Judicial de la Federación y el Poder Legislativo Federal, así como los órganos constitucionales autónomos, ejerzan para la realización de actividades en materia de estadística y geografía de interés nacional, invariablemente deberán registrarse en las partidas de gasto correspondientes. Cuando las entidades federativas y los municipios reciban recursos federales para los fines descritos, quedarán obligados a identificarlos e informar al Instituto sobre ellos.</p><p>Las Unidades podrán realizar Actividades Estadísticas y Geográficas, siempre que hayan informado al respecto al Instituto, durante el primer trimestre del ejercicio fiscal, quien analizará si dichas Actividades se apegan a los programas a que se refiere el artículo 9 de esta Ley y emitirá opinión sobre la pertinencia de realizar dichas Actividades y, en su caso, formulará las recomendaciones que estime pertinentes para llevarlas a cabo.</p><p>La Secretaría de Hacienda y Crédito Público tomará medidas para evitar la duplicidad en las Actividades Estadísticas y Geográficas, con el objeto de optimizar la asignación de recursos públicos federales para dichas Actividades.</p><p>Lo previsto en el presente artículo, será aplicable, tratándose de los organismos constitucionales autónomos, sólo a aquellos que reciban recursos del Presupuesto de Egresos de la Federación.</p><p>SECCIÓN VI De la Transparencia y Rendición de Cuentas del Instituto</p>','ordinario',85,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('f717750a-2ee7-5081-ae12-a3122faf744e'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 86','<p>ARTÍCULO 86.- El Instituto deberá presentar en marzo de cada año al Ejecutivo Federal y al Congreso de la Unión:</p><p>I. Los resultados de la ejecución del Programa Anual de Información Estadística y Geográfica correspondiente al año inmediato anterior;</p><p>II. Un informe de las actividades de los Comités de los Subsistemas, y</p><p>III. Su informe anual de actividades y sobre el ejercicio del gasto correspondiente al ejercicio inmediato anterior, incluyendo las observaciones relevantes que, en su caso, haya formulado el auditor externo.</p><p>Cada seis años, el Instituto enviará al Ejecutivo Federal y al Congreso de la Unión, junto con la información a que se refieren las fracciones anteriores, el resultado de la evaluación del Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica.</p><p>Cualquiera de las Cámaras del Congreso de la Unión podrá citar al Presidente para que rinda informes sobre las políticas y actividades del Instituto.</p><p>El Instituto deberá hacer del conocimiento público la información a que se refieren las fracciones anteriores, sujetándose a las disposiciones de carácter general que expida al efecto.</p><p>Lo dispuesto en este artículo se realizará sin perjuicio de los datos e informes que el Instituto deba rendir en términos de la Ley Federal de Presupuesto y Responsabilidad Hacendaria, de la Ley de Fiscalización Superior de la Federación y demás disposiciones aplicables.</p>','ordinario',86,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('bbafabfd-4ffa-570e-ba2e-574cba9dec07'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 87','<p>ARTÍCULO 87.- El Instituto deberá dar a conocer a los Poderes de la Unión y al público en general el calendario anual de publicación aprobado por la Junta de Gobierno, mismo que podrá ser revisado en forma trimestral.</p>','ordinario',87,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('ae086f6a-b27e-5c5c-96c9-331113ef3b22'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 88','<p>ARTÍCULO 88.- El Instituto deberá definir las metodologías que habrán de utilizarse en la realización de las Actividades Estadísticas y Geográficas, a través de Internet, antes de su implantación, a fin de recibir y, en su caso, atender las observaciones que se formulen al efecto.</p><p>De igual forma, el Instituto deberá dar a conocer y conservar los metadatos o especificaciones concretas de la aplicación de las metodologías que se hubieren utilizado en la elaboración de la Información.</p><p>A fin de dar cumplimiento a lo dispuesto en el presente artículo, la Junta de Gobierno deberá expedir los lineamientos generales que habrán de seguirse para publicar dichas metodologías y atender las observaciones que, en su caso, se reciban.</p>','ordinario',88,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('2e08d1fa-2da4-5394-b03a-1ec6cac27673'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 89','<p>ARTÍCULO 89.- El Instituto invitará, a solicitud de los Comités Ejecutivos, a organismos internacionales a revisar y opinar respecto de las metodologías que se utilicen para generar la Información, incluyendo las que el mismo aplique. El resultado de tales inspecciones deberá incluirse en los informes a los que hace alusión el artículo 86 de esta Ley.</p>','ordinario',89,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('6a2bad24-57bd-5a0b-b1e3-b379d9ff5c21'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 90','<p>ARTÍCULO 90.- El Instituto deberá hacer del conocimiento público, a través de Internet, los convenios de intercambio de información que celebre con otros organismos o agencias nacionales o extranjeras.</p><p>La Junta de Gobierno, previa justificación, podrá determinar excepciones a la divulgación de la información a que se refiere el párrafo anterior.</p>','ordinario',90,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('b8788a49-adb1-53f1-abf5-9f6a04c3c2bd'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 91','<p>ARTÍCULO 91.- El Órgano Interno de Control es un órgano dotado de autonomía técnica y de gestión para decidir sobre su funcionamiento y resoluciones. Tendrá a su cargo prevenir, corregir, investigar y calificar actos u omisiones que pudieran constituir responsabilidades administrativas de servidores públicos del Instituto y de particulares vinculados con faltas graves; para sancionar aquellas distintas a las que son competencia del Tribunal Federal de Justicia Administrativa; revisar el ingreso, egreso, manejo, custodia, aplicación de recursos públicos federales; así como presentar las denuncias por hechos u omisiones que pudieran ser constitutivos de delito ante la Fiscalía Especializada en Combate a la Corrupción.</p><p>El Órgano Interno de Control tendrá un titular que lo representará y contará con la estructura orgánica, personal y recursos necesarios para el cumplimiento de su objeto.</p><p>En el desempeño de su cargo, el titular del Órgano Interno de Control se sujetará a los principios previstos en la Ley General de Responsabilidades Administrativas.</p><p>El Órgano Interno de Control tendrá las siguientes atribuciones:</p><p>I. Las que contempla la Ley General de Responsabilidades Administrativas;</p><p>II. Verificar que el ejercicio de gasto del Instituto se realice conforme a la normatividad aplicable, los programas aprobados y montos autorizados;</p><p>III. Presentar a la Junta de Gobierno del Instituto los informes de las revisiones y auditorías que se realicen para verificar la correcta y legal aplicación de los recursos y bienes del Instituto;</p><p>IV. Revisar que las operaciones presupuestales que realice el Instituto, se hagan con apego a las disposiciones legales y administrativas aplicables y, en su caso, determinar las desviaciones de las mismas y las causas que les dieron origen;</p><p>V. Promover ante las instancias correspondientes, las acciones administrativas y legales que se deriven de los resultados de las auditorías;</p><p>VI. Investigar, en el ámbito de su competencia, los actos u omisiones que impliquen alguna irregularidad o conducta ilícita en el ingreso, egreso, manejo, custodia y aplicación de fondos y recursos del Instituto;</p><p>VII. Evaluar los informes de avance de la gestión financiera respecto de los programas autorizados y los relativos a procesos concluidos, empleando la metodología que determine el Órgano Interno de Control;</p><p>VIII. Evaluar el cumplimiento de los objetivos y metas fijadas en los programas de naturaleza administrativa contenidos en el presupuesto de egresos del Instituto, empleando la metodología que determine;</p><p>IX. Recibir quejas y denuncias conforme a las leyes aplicables;</p><p>X. Solicitar la información y efectuar visitas a las áreas y órganos del Instituto para el cumplimento de sus funciones;</p><p>XI. Recibir, tramitar y resolver las inconformidades, procedimientos y recursos administrativos que se promuevan en materia de adquisiciones, arrendamientos, servicio y obras públicas;</p><p>XII. Intervenir en los actos de entrega-recepción de los servidores públicos del Instituto de mandos medios y superiores, en los términos de la normativa aplicable;</p><p>XIII. Participar, conforme a las disposiciones vigentes, en los comités y subcomités de los que el Órgano Interno de Control forme parte, e intervenir en los actos que se deriven de los mismos;</p><p>XIV. Atender las solicitudes de los diferentes órganos del Instituto en los asuntos de su competencia;</p><p>XV. Proponer los proyectos de modificación o actualización de su estructura orgánica, personal y/o recursos;</p><p>XVI. Formular el anteproyecto de presupuesto del Órgano Interno de Control;</p><p>XVII. Presentar a la Junta de Gobierno del Instituto los informes previo y anual de resultados de su gestión, y comparecer ante el mismo, cuando así lo requiera el Presidente del Instituto;</p><p>XVIII. Presentar a la Junta de Gobierno del Instituto los informes respecto de los expedientes relativos a las faltas administrativas y, en su caso, sobre la imposición de sanciones en materia de responsabilidades administrativas, y</p><p>XIX. Las demás que le confieran otros ordenamientos.</p><p>Artículo reformado DOF 27-01-2017</p><p>ARTÍCULO 91 BIS.- El titular del Órgano Interno de Control será designado por la Cámara de Diputados del Congreso de la Unión, con el voto de las dos terceras partes de sus miembros presentes, conforme al procedimiento establecido en la Ley Orgánica del Congreso General de los Estados Unidos Mexicanos. Artículo adicionado DOF 27-01-2017</p><p>ARTÍCULO 91 TER.- El titular del Órgano Interno de Control durará en su encargo cuatro años y podrá ser designado por un periodo inmediato posterior al que se haya desempeñado, previa postulación y cumpliendo los requisitos previstos en esta Ley y el procedimiento establecido en la Ley Orgánica del Congreso General de los Estados Unidos Mexicanos.</p><p>Tendrá un nivel jerárquico igual al de un Director General o su equivalente en la estructura orgánica del Instituto y mantendrá la coordinación técnica necesaria con la Entidad de Fiscalización Superior de la Federación a que se refiere el artículo 79 de la Constitución Política de los Estados Unidos Mexicanos.</p><p>El titular del Órgano Interno de Control deberá rendir informe semestral y anual de actividades al Instituto, del cual marcará copia a la Cámara de Diputados.</p><p>El titular del Órgano Interno de Control se abstendrá de desempeñar cualquier otro empleo, trabajo o comisión públicos o privados, con excepción de los cargos docentes. Artículo adicionado DOF 27-01-2017</p><p>ARTÍCULO 91 QUÁTER.- El Titular del Órgano Interno de Control deberá reunir los siguientes requisitos:</p><p>I. Ser ciudadano mexicano en pleno goce de sus derechos civiles y políticos, y tener treinta y cinco años cumplidos el día de la designación;</p><p>II. Gozar de buena reputación y no haber sido condenado por delito doloso que amerite pena de prisión por más de un año;</p><p>III. Contar al momento de su designación con una experiencia de al menos cinco años en el control, manejo o fiscalización de recursos, responsabilidades administrativas, contabilidad gubernamental, auditoría gubernamental, obra pública, adquisiciones, arrendamientos y servicios del sector público;</p><p>IV. Contar al día de su designación, con antigüedad mínima de cinco años, con título profesional relacionado con las actividades a que se refiere la fracción anterior, expedido por autoridad o institución legalmente facultada para ello;</p><p>V. Contar con reconocida solvencia moral;</p><p>VI. No pertenecer o haber pertenecido en los cuatro años anteriores a su designación, a despachos de consultoría o auditoría que hubieren prestado sus servicios al Instituto, o haber fungido como consultor o auditor externo del Instituto, en lo individual durante ese periodo;</p><p>VII. No estar inhabilitado para desempeñar un empleo, cargo o comisión en el servicio público, y</p><p>VIII. No haber sido Secretario de Estado, Procurador o Fiscal General de la República o Procurador o Fiscal de Justicia de alguna de las entidades federativas, Oficial Mayor de un ente público, Senador, Diputado Federal, Gobernador de algún Estado o Jefe de Gobierno de la Ciudad de</p><p>México, dirigente, miembro de órgano rector, alto ejecutivo o responsable del manejo de los recursos públicos de algún partido político, ni haber sido postulado para cargo de elección popular en los cuatro años anteriores a la propia designación. Fracción reformada DOF 20-05-2021 Artículo adicionado DOF 27-01-2017</p><p>ARTÍCULO 91 QUINQUIES.- El Titular del Órgano Interno de Control del Instituto será sujeto de responsabilidad administrativa en términos de la Ley General de Responsabilidades Administrativas; y podrá ser sancionado de conformidad con el procedimiento previsto en la normatividad aplicable.</p><p>Tratándose de los demás servidores públicos adscritos al Órgano Interno de Control del Instituto serán sancionados por el Titular del Órgano Interno de Control, o por la persona en quien delegue la facultad, en términos de la Ley General de Responsabilidades Administrativas. Artículo adicionado DOF 27-01-2017</p><p>De los Registros Nacionales de Información Estadística y Geográfica a cargo del Instituto</p>','ordinario',91,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('c93f8426-cf4c-59e1-b536-7b701eab92b0'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 92','<p>ARTÍCULO 92.- El Instituto deberá establecer, operar y normar el Registro Nacional de Información Geográfica, en el que deberá incluirse por lo menos la información proveniente de los temas geográficos a que se refiere el artículo 26 de esta Ley, así como el Registro Estadístico Nacional, en el que deberá asentarse por lo menos el Registro de Instituciones y Unidades Administrativas con Funciones Estadísticas del Sector Público y el Inventario Nacional de Estadística del Sector Público.</p>','ordinario',92,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('88c7dc7d-4c0a-5231-ad5c-31741032e5de'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 93','<p>ARTÍCULO 93.- La inscripción que sobre los catastros de los municipios y de las entidades federativas deba hacerse en el Registro Nacional de Información Geográfica, comprenderá la representación cartográfica y la base de datos de los predios rústicos y urbanos de su jurisdicción.</p><p>En caso de que no se cuente con la cartografía y la base de datos a que se refiere el párrafo anterior, se registrarán los datos que se encuentren en los padrones, croquis y fichas catastrales.</p><p>El Instituto, con la intervención de las autoridades que resulten competentes, podrá efectuar los trabajos cartográficos en cumplimiento de tratados o convenios internacionales y con la participación de los gobiernos de las entidades federativas que corresponda, en la definición y demarcación de límites internacionales, incluyendo la zona económica exclusiva.</p>','ordinario',93,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('b6ed1bca-5e49-513d-b0e4-4246bf0c39e9'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 94','<p>ARTÍCULO 94.- El Instituto establecerá, operará y normará el inventario y el directorio señalados en los artículos 20 y 23, respectivamente y podrá establecer, operar y normar otros registros que para fines estadísticos o geográficos estime necesarios.</p>','ordinario',94,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('cb7d7a17-1924-5d5a-9566-a4dea18da955'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 95','<p>ARTÍCULO 95.- Las personas físicas con actividades empresariales y las personas morales, sin incluir a las del sector público, estarán obligadas a inscribirse en el Directorio Nacional de Unidades Económicas que lleve el Instituto y a mantener actualizada su inscripción, conforme a las disposiciones que al efecto emita el Instituto.</p><p>Las Unidades encargadas de los registros administrativos que permitan obtener Información de Interés Nacional, deberán proporcionar al Instituto la información que requiera para la creación y actualización del Directorio Nacional de Unidades Económicas.</p><p>Del Acervo de Información</p>','ordinario',95,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('88555494-1a0c-5f74-8213-1ec5337404b3'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 96','<p>ARTÍCULO 96.- El Instituto deberá conservar la Información de Interés Nacional que elaboren el propio Instituto y las Unidades, en términos de lo dispuesto en esta Ley y en las disposiciones de carácter general que al efecto emita.</p><p>Cuando una Unidad desaparezca o se desincorpore, el Instituto deberá conservar la Información generada por la misma.</p>','ordinario',96,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('80d1f577-a09b-5baa-a4d4-ec1ca4a76673'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 97','<p>ARTÍCULO 97.- El Instituto implementará un sistema de compilación normativa, en el que se conservarán los textos de las normas que en el ejercicio de sus funciones expida.</p><p>Del Servicio Público de Información Estadística y Geográfica</p>','ordinario',97,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('ee6d16dd-19eb-5975-848c-3c3a4eb47c06'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 98','<p>ARTÍCULO 98.- El Servicio Público de Información Estadística y Geográfica consiste en poner a disposición de los usuarios, sujeto a las normas que al efecto dicte la Junta de Gobierno, la totalidad de la Información de Interés Nacional.</p>','ordinario',98,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('b95b3943-7d1f-5702-8700-fab7548fcd6e'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 99','<p>ARTÍCULO 99.- El Servicio Público de Información Estadística y Geográfica será prestado en forma exclusiva por el Instituto. Lo anterior, sin perjuicio de que las propias Unidades den a conocer la Información que generen identificándola como parte del Sistema.</p><p>El Instituto podrá autorizar que otras instancias de gobierno o particulares, presten el Servicio Público de Información Estadística y Geográfica, conforme a las reglas que al efecto expida la Junta de Gobierno.</p><p>El Instituto pondrá la Información de Interés Nacional a disposición de los usuarios a través de Internet, así como en los centros de consulta que al efecto establezca el propio Instituto en el territorio nacional.</p><p>Las consultas que realicen los usuarios a través de los medios previstos en el párrafo inmediato anterior, serán ofrecidas por el Instituto en forma gratuita.</p><p>El Instituto pondrá a disposición de los usuarios información de la red geodésica nacional, con el objeto de que sus estudios geográficos estén vinculados con la red mencionada.</p>','ordinario',99,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('c1573ace-6530-56d4-bffd-9cf67e9cf5eb'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 100','<p>ARTÍCULO 100.- El Instituto, siguiendo las mejores prácticas internacionales, pondrá a disposición de quien lo solicite, los microdatos de las encuestas nacionales y muestras representativas de los operativos censales que realice con la mayor desagregación posible, sin violar la confidencialidad y reserva de la información básica establecidas en la presente Ley. La Junta de Gobierno deberá establecer los procedimientos y condiciones para facilitar el acceso a dicha información de manera expedita.</p>','ordinario',100,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('4051ff55-b169-5d59-9a3c-6b768c7e1dd5'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 101','<p>ARTÍCULO 101.- Cuando a petición de algún usuario se requiera al Instituto copia, copia certificada o cualquier clase de impresión o respaldo de la Información de Interés Nacional, ésta se entregará al usuario en los términos que fijen las disposiciones correspondientes y previa recepción del pago de los derechos que para estos casos establezca la Ley Federal de Derechos.</p>','ordinario',101,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('fe2e4d7e-b472-5fff-a819-dd03f4dcb426'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 102','<p>ARTÍCULO 102.- El Instituto no estará obligado a proporcionar aquella información que:</p><p>I. Tenga en virtud de cualquier disposición legal el carácter de confidencial, clasificada, reservada o de cualquier otra forma se encuentre restringida su difusión, o</p><p>II. El usuario la requiera procesada en cualquier forma distinta a como se encuentra disponible, sin perjuicio de que el Instituto la pueda procesar y poner a disposición de los usuarios en forma</p><p>onerosa, sujetándose en todo caso a los principios de confidencialidad, accesibilidad y transparencia.</p><p>TÍTULO CUARTO DE LAS FALTAS ADMINISTRATIVAS Y DE LAS SANCIONES</p><p>De las Faltas Administrativas</p>','ordinario',102,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('f1d7067a-7e73-5e14-a9af-5a2db2c11177'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 103','<p>ARTÍCULO 103.- Cometen infracciones a lo dispuesto por esta Ley, quienes en calidad de Informantes del Sistema:</p><p>I. Se nieguen a proporcionar datos, informes o a exhibir documentos cuando deban hacerlo, dentro del plazo que se les hubiere señalado;</p><p>II. Suministren datos falsos, incompletos o incongruentes;</p><p>III. Omitan inscribirse en los registros establecidos por esta Ley o no proporcionen la información que para éstos se requiera;</p><p>IV. Se opongan a las inspecciones de verificación que en cumplimiento de las disposiciones de esta Ley realicen los inspectores, recolectores o censores y en general de cualquier representante de cualquiera de las Unidades que se encuentre facultado para ello, y</p><p>V. Utilicen indebidamente las denominaciones censo nacional o cuentas nacionales.</p><p>También cometen infracción a la presente Ley quienes se nieguen a desempeñar funciones censales.</p><p>Los actos u omisiones en que incurran las personas morales que impidan el desarrollo normal de los levantamientos censales o de los procesos de generación de Información, también serán considerados infracciones a la presente Ley.</p>','ordinario',103,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('6c877c10-e9b6-5a7a-ba3d-954e45f5a131'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 104','<p>ARTÍCULO 104.- Son infracciones imputables a los servidores públicos del Instituto o a los servidores públicos de las Unidades las siguientes:</p><p>I. La revelación de datos confidenciales;</p><p>II. La violación de las reservas de los secretos de carácter industrial o comercial o de cualquier otro tipo, o el suministro en forma nominativa o individualizada de los datos proporcionados por los Informantes del Sistema;</p><p>III. La inobservancia de la reserva en materia de Información, cuando por causas de seguridad nacional hubiese sido declarada de divulgación restringida por la Junta de Gobierno;</p><p>IV. La participación deliberada en cualquier acto u omisión que entorpezca el desarrollo normal de los levantamientos censales o de los procesos de generación de Información;</p><p>V. Impedir, sin justificación, el libre ejercicio de los derechos de acceso y rectificación de datos, cuando estuvieren a cargo de los registros administrativos establecidos por Ley, y</p><p>VI. Impedir el acceso del público a la Información a que tenga derecho.</p>','ordinario',104,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('0f98ef8b-2a19-593b-8f65-e3caf4212c3e'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 105','<p>ARTÍCULO 105.- Se reputarán infracciones de los recolectores o censores y auxiliares, cuando:</p><p>I. Se nieguen a cumplir con las funciones que les sean encomendadas;</p><p>II. Violen la confidencialidad de los datos que se hayan captado para efectos estadísticos o revelen en forma nominativa o individualizada dichos datos, y</p><p>III. Cometan actos o incurran en omisiones que impidan el desarrollo normal de los levantamientos censales o de los procesos de generación de Información.</p><p>Para los efectos de este Título, serán considerados como recolectores o censores, las personas a las que el Instituto encomiende labores propias de recolección y recopilación de Información en forma periódica o durante el levantamiento censal, y como auxiliares, a quienes desempeñen cualquier otra actividad relacionada con el proceso de elaboración de la estadística y la obtención de datos de carácter geográfico.</p><p>De las Sanciones</p>','ordinario',105,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('2007d330-72ce-5502-a69f-79c20ed412a8'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 106','<p>ARTÍCULO 106.- Las infracciones a lo dispuesto por el artículo 103 de esta Ley, serán sancionadas con multa de:</p><p>I. Para las establecidas en las fracciones I, II y IV, de 5 hasta 500 salarios.</p><p>Cuando se trate de censos económicos o encuestas en establecimientos, la multa será de 3,000 hasta 30,000 salarios;</p><p>Cuando los Informantes del Sistema tengan el carácter de concesionarios o autorizados de telecomunicaciones o de radiodifusión, la multa será de 30,000 hasta 40,000 salarios; Párrafo adicionado DOF 14-07-2014</p><p>II. Para la establecida en la fracción III, de 200 hasta 500 salarios;</p><p>Cuando los Informantes del Sistema tengan el carácter de concesionarios o autorizados de telecomunicaciones o de radiodifusión, la multa será de 20,000 hasta 30,000 salarios; Párrafo adicionado DOF 14-07-2014</p><p>III. Para las establecidas en la fracción V y en el último párrafo, de 3,000 hasta 10,000 salarios, y</p><p>Cuando los Informantes del Sistema tengan el carácter de concesionarios o autorizados de telecomunicaciones o de radiodifusión, la multa será de 10,000 hasta 20,000 salarios; Párrafo adicionado DOF 14-07-2014</p><p>IV. Para la establecida en el penúltimo párrafo, de 5 a 100 salarios.</p><p>Cuando los Informantes del Sistema tengan el carácter de concesionarios o autorizados de telecomunicaciones o de radiodifusión, la multa será de 1,000 hasta 10,000 salarios. Párrafo adicionado DOF 14-07-2014</p>','ordinario',106,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('f1003d12-c361-54e5-b736-dfbc800c5207'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 107','<p>ARTÍCULO 107.- Las infracciones a lo dispuesto por el artículo 104 de esta Ley, tratándose de servidores públicos de las Unidades, serán sancionadas con multa de:</p><p>I. Para las establecidas en las fracciones I, II y III, de 500 hasta 10,000 salarios;</p><p>II. Para la establecida en la fracción IV, de 200 hasta 500 salarios, y</p><p>III. Para las establecidas en las fracciones V y VI, de 500 hasta 1,000 salarios.</p>','ordinario',107,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('51ee714f-7b5b-5b91-9886-3f5d13f953ae'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 108','<p>ARTÍCULO 108.- Las infracciones a lo dispuesto por el artículo 104 de esta Ley, tratándose de servidores públicos del Instituto, serán sancionadas con multa de:</p><p>I. Para las establecidas en las fracciones I, II y III, de 2,000 hasta 30,000 salarios;</p><p>II. Para la establecida en la fracción IV, de 400 hasta 1,000 salarios, y</p><p>III. Para las establecidas en las fracciones V y VI, de 1,000 hasta 2,000 salarios.</p>','ordinario',108,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('e1175487-5849-51db-98dd-dc22062d87d5'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 109','<p>ARTÍCULO 109.- Las infracciones a lo dispuesto por el artículo 105 de esta Ley, serán sancionadas con multa de:</p><p>I. Para la establecida en la fracción I, de 100 hasta 500 salarios, y</p><p>II. Para las establecidas en las fracciones II y III, de 500 hasta 1,000 salarios.</p>','ordinario',109,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('561992e3-d407-5ba7-bfe4-f8207659f7cd'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 110','<p>ARTÍCULO 110.- Para los efectos de este Capítulo, por salario se entiende el salario mínimo general diario vigente en el Distrito Federal, al momento de cometerse la infracción.</p>','ordinario',110,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('be5e0e96-bd3b-52a9-b002-d0335a285fb7'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 111','<p>ARTÍCULO 111.- Para la imposición de las sanciones, el Instituto tomará en cuenta la gravedad de la infracción, las condiciones del infractor y la conveniencia de evitar prácticas tendientes a contravenir las disposiciones de esta Ley.</p><p>Estas multas las determinará el Instituto y serán ejecutadas por el Servicio de Administración Tributaria, a través de los procedimientos y disposiciones aplicables por dicho órgano. Párrafo adicionado DOF 14-07-2014</p>','ordinario',111,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('3d18ffbb-2264-5fd7-8f8a-f0c9f0a804a4'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 112','<p>ARTÍCULO 112.- Las sanciones en materia de responsabilidad administrativa de los servidores públicos previstas en esta Ley, serán aplicadas por la autoridad competente para sustanciar el procedimiento respectivo de conformidad con las leyes especiales y las disposiciones aplicables, sin perjuicio de otras responsabilidades que resulten. Cuando el Instituto tenga conocimiento de alguna infracción a la Ley, lo deberá hacer del conocimiento de la autoridad que corresponda.</p><p>TÍTULO QUINTO DEL RECURSO DE REVISIÓN</p>','ordinario',112,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('dda65648-cdc1-595e-b3b2-04bbb2c94f3a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 113','<p>ARTÍCULO 113.- En contra de los actos o resoluciones que dicte el Instituto, el interesado podrá interponer ante éste, el recurso de revisión o, cuando proceda, intentar la vía jurisdiccional que corresponda.</p>','ordinario',113,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('10481011-a60d-51d6-b6a4-783e8a616308'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 114','<p>ARTÍCULO 114.- El plazo para interponer el recurso de revisión, será de quince días contados a partir del día siguiente a aquél en que hubiere surtido efectos la notificación de la resolución o se tenga conocimiento del acto que se recurra.</p>','ordinario',114,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('7dafb00d-0cb3-51fc-bb36-89b33b296b81'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 115','<p>ARTÍCULO 115.- El escrito de interposición del recurso de revisión deberá presentarse ante el propio Instituto y será resuelto por el superior jerárquico del servidor público que haya emitido la resolución impugnada o haya realizado el acto impugnado, salvo que se trate de resoluciones o actos del Presidente del Instituto, en cuyo caso será resuelto por la Junta de Gobierno. Dicho escrito deberá expresar:</p><p>I. El nombre del recurrente, y del tercero perjudicado si lo hubiere, así como el lugar que señale para efectos de notificaciones;</p><p>II. El acto o resolución que se recurre y fecha en que se le notificó o tuvo conocimiento del mismo;</p><p>III. Los agravios que se causan al recurrente, y</p><p>IV. Las pruebas que ofrezca, que tengan relación inmediata y directa con la resolución o acto de que se trate.</p><p>El escrito de interposición del recurso a que se refiere este artículo, deberá ser acompañado del documento que acredite la personalidad del promovente cuando actúe en nombre de otro o de personas morales, de una copia de la resolución o acto que se impugna y, en su caso, de la notificación correspondiente, así como de la documentación que ofrezca como prueba. Tratándose de solicitudes que por no haberse resuelto en tiempo se entiendan negadas, deberá acompañarse el escrito de iniciación del procedimiento, o el documento sobre el cual no hubiere recaído resolución alguna.</p>','ordinario',115,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('7a486822-172f-56fd-b4cf-38a50661969c'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 116','<p>ARTÍCULO 116.- La interposición del recurso de revisión suspenderá la ejecución de la resolución o del acto impugnado, siempre y cuando:</p><p>I. Lo solicite expresamente el recurrente;</p><p>II. Sea procedente el recurso;</p><p>III. No se siga perjuicio al interés social, y</p><p>IV. Tratándose de multas, el recurrente garantice el crédito fiscal en cualquiera de las formas previstas en el Código Fiscal de la Federación.</p><p>El Instituto deberá acordar, en su caso, la suspensión o la denegación de la suspensión dentro de los cinco días siguientes al de la interposición del recurso de revisión.</p>','ordinario',116,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('bcb868b1-cf86-55e0-a030-fc4b24476f2f'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 117','<p>ARTÍCULO 117.- El recurso de revisión se tendrá por no interpuesto y se desechará cuando:</p><p>I. Se presente fuera de plazo;</p><p>II. No se acredite la personalidad del recurrente, y</p><p>III. No aparezca suscrito por quien deba hacerlo, a menos que se firme antes del vencimiento del plazo para interponerlo.</p>','ordinario',117,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('b5fa9152-b543-5360-b579-622b31cb4027'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 118','<p>ARTÍCULO 118.- Se desechará por improcedente el recurso de revisión cuando éste se interponga contra actos o resoluciones:</p><p>I. Que sean materia de otro recurso o medio de defensa que se encuentre pendiente de resolución, presentado por el mismo promovente y por el mismo acto o resolución impugnado;</p><p>II. Que no afecten los intereses jurídicos del promovente;</p><p>III. Consumados de un modo irreparable, y</p><p>IV. Consentidos expresamente.</p>','ordinario',118,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('5c26f0f9-0969-5117-ab84-3b3fe845766a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 119','<p>ARTÍCULO 119.- Será sobreseído el recurso cuando:</p><p>I. El promovente se desista expresamente del recurso;</p><p>II. El agraviado fallezca durante el procedimiento, si el acto respectivo sólo afecta a su persona;</p><p>III. Durante el procedimiento sobrevenga alguna de las causas de improcedencia a que se refiere el artículo anterior, y</p><p>IV. Cuando hayan cesado los efectos del acto respectivo.</p>','ordinario',119,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('59096b7a-d4c0-56c1-bff8-1a8134f28c31'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 120','<p>ARTÍCULO 120.- La autoridad encargada de resolver el recurso de revisión podrá:</p><p>I. Desecharlo por improcedente o sobreseerlo;</p><p>II. Confirmar el acto impugnado;</p><p>III. Declarar la inexistencia del acto impugnado o revocarlo total o parcialmente, y</p><p>IV. Modificar u ordenar la modificación del acto impugnado o dictar u ordenar expedir uno nuevo que lo sustituya, cuando el recurso interpuesto sea total o parcialmente resuelto a favor del recurrente.</p>','ordinario',120,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('7087570e-bf94-5df7-8475-9cc95e036f8a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 121','<p>ARTÍCULO 121.- La resolución del recurso de revisión se fundará en derecho y examinará todos y cada uno de los agravios hechos valer por el recurrente, teniendo la autoridad la facultad de invocar hechos notorios; pero cuando uno de los agravios sea suficiente para desvirtuar la validez del acto impugnado bastará con el examen de dicho punto.</p><p>La autoridad, en beneficio del recurrente, podrá examinar en su conjunto los agravios, así como los demás razonamientos del recurrente, a fin de resolver la cuestión efectivamente planteada, pero sin cambiar los hechos expuestos en el recurso.</p><p>Igualmente, la autoridad deberá dejar sin efectos legales los actos administrativos cuando advierta una ilegalidad manifiesta y los agravios sean insuficientes, pero deberá fundar cuidadosamente los motivos por los que consideró ilegal el acto y precisar el alcance en la resolución.</p><p>Si la resolución ordena realizar un determinado acto o iniciar la reposición del procedimiento, deberá cumplirse en un plazo de cuatro meses.</p>','ordinario',121,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('27a60d02-b5da-59d3-aa76-806ec1ff7587'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 122','<p>ARTÍCULO 122.- No se podrán revocar o modificar los actos o resoluciones administrativos en la parte no impugnada por el recurrente.</p><p>La resolución expresará con claridad los actos que se modifiquen y si la modificación es parcial, se precisará ésta.</p>','ordinario',122,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('dad0d0d1-1d26-51bf-84d8-64ad7ec32be1'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 123','<p>ARTÍCULO 123.- El recurrente podrá esperar la resolución expresa o impugnar, en un plazo de cuatro meses contados a partir de la presentación del recurso, la presunta confirmación del acto impugnado.</p>','ordinario',123,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('26329623-1555-503c-9575-620681c84c5c'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 124','<p>ARTÍCULO 124.- La autoridad ante la cual se tramite el recurso podrá dejar sin efectos un requerimiento o una sanción, de oficio o a petición de parte interesada, cuando se trate de un error manifiesto o el particular demuestre que ya había dado cumplimiento con anterioridad.</p>','ordinario',124,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('e7abd95f-ecb1-571c-a9a3-ac9eb47d8159'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 125','<p>ARTÍCULO 125.- Cuando haya de tenerse en cuenta nuevos hechos o documentos que no obren en el expediente original derivado del acto impugnado, se pondrá de manifiesto a los interesados para que, en un plazo no inferior a cinco días ni superior a diez, formulen sus alegatos y presenten los documentos que estimen procedentes.</p><p>No se tomarán en cuenta en la resolución del recurso de revisión, hechos, documentos o alegatos del recurrente, cuando habiendo podido aportarlos durante el procedimiento administrativo no lo haya hecho.</p>','ordinario',125,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('588f1cdc-da93-517a-8615-202d8583af6d'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Artículo 126','<p>ARTÍCULO 126.- A lo dispuesto por el presente Capítulo se aplicará supletoriamente el Código Nacional de Procedimientos Civiles y Familiares. Artículo reformado DOF 14-11-2025</p>','ordinario',126,'Ley del Sistema Nacional de Información Estadística y Geográfica',null,null) on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('a01e04c2-cc7d-5489-8939-e5bed85d27b9'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Primero','<p>PRIMERO.- La presente Ley entrará en vigor noventa días naturales después de su publicación en el Diario Oficial de la Federación, salvo lo dispuesto por el segundo párrafo del artículo 23 de presente ordenamiento, que entrará en vigor el 1 de agosto de 2010 y por la fracción III del artículo 59 de esta Ley que entrará en vigor tres años después de la entrada en vigor de la presente Ley, debiéndose aplicar entre tanto lo dispuesto en el artículo undécimo transitorio.</p>','transitorio',127,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('f4738b85-e231-5ff1-8513-04a3c9f7da2a'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Segundo','<p>SEGUNDO.- La designación de los primeros integrantes de la Junta de Gobierno del Instituto se realizará en los términos previstos en la presente Ley, dentro de los 90 días naturales siguientes a la publicación de la misma en el Diario Oficial de la Federación.</p><p>El periodo del primer Presidente del Instituto vencerá el 31 de diciembre de 2009. Los periodos de los primeros vicepresidentes de la Junta de Gobierno vencerán los días 31 de diciembre de 2008, 2010, 2012 y 2014, respectivamente, debiendo señalar el Ejecutivo Federal cuál de los citados periodos corresponde a cada miembro de la Junta de Gobierno.</p>','transitorio',128,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('a276dd11-a1d7-5345-970f-cb2a7e199539'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Tercero','<p>TERCERO.- El Instituto Nacional de Estadística y Geografía (INEGI), tendrá la titularidad de todos los bienes, derechos y obligaciones propiedad del Gobierno Federal que estuvieran adscritos o destinados bajo cualquier título al servicio del Instituto Nacional de Estadística, Geografía e Informática, órgano desconcentrado de la Secretaría de Hacienda y Crédito Público.</p><p>También forman parte del patrimonio del Instituto, todos aquellos bienes muebles e inmuebles pertenecientes a la Federación que, a la entrada en vigor del presente Decreto, venía utilizando el órgano desconcentrado señalado en el párrafo precedente, por lo que en un plazo no mayor de un año contado a partir de la entrada en vigor de este Decreto, se deberán haber concluido los trámites correspondientes para su formalización. Los bienes muebles se transferirán al patrimonio del Instituto en los términos previstos por el Título quinto de la Ley General de Bienes Nacionales y las disposiciones que regulan su registro, afectación, disposición y baja.</p><p>Los bienes inmuebles, incluyendo terreno y construcciones, que se incorporan como parte del patrimonio del Instituto son los ubicados en:</p><p>a) Av. Héroe de Nacozari Sur No. 2301, Fraccionamiento Jardines del Parque, Aguascalientes, Aguascalientes, C.P. 20270;</p><p>b) Av. Héroe de Nacozari Sur No. 2302, Fraccionamiento Rinconada del Parque, Aguascalientes, Aguascalientes, C.P. 20277;</p><p>c) Av. Héroe de Nacozari Sur No. 2304, Fraccionamiento Rinconada del Parque, Aguascalientes, Aguascalientes, C.P. 20277;</p><p>d) Av. de la Convención Oriente No. 902, Edificio 2, Fraccionamiento Primo Verdad, Aguascalientes, Aguascalientes, C.P. 20267;</p><p>e) Calle Selenio No. 107, Ciudad Industrial, Durango, Durango, C.P. 34208;</p><p>f) Av. Patriotismo No. 711-A, Col. San Juan, Delegación Benito Juárez, México, Distrito Federal, C.P. 03730;</p><p>g) Av. Baja California No. 272, Col. Hipódromo, Delegación Cuauhtémoc, México, Distrito Federal, C.P. 06100;</p><p>h) Balderas No. 71, Col. Centro, Delegación Cuauhtémoc, México, Distrito Federal, C.P. 06040;</p><p>i) Av. 16 de Septiembre No. 670, Col. Mexicaltzingo, Sector Juárez, Guadalajara, Jalisco, C.P. 44180;</p><p>j) Paseo Río Sonora Sur y Comonfort S/N, Col. Proyecto Río Sonora, Edificio México (4o. Piso), Hermosillo, Sonora, C.P. 83270;</p><p>k) Paseo Río Sonora Sur y Comonfort S/N, Col. Proyecto Río Sonora, Edificio México (Planta Baja), Hermosillo, Sonora, C.P. 83270, y</p><p>l) Calle 60 x 39 y 41 No. 378, Col. Centro, Mérida, Yucatán, C.P. 97000.</p><p>Respecto de los inmuebles ubicados en Calle el Novillo No. 610, Fraccionamiento Ojocaliente II, Aguascalientes, Aguascalientes, C.P. 20196, en donde se encuentra ubicada la Biblioteca Ludoteca, así como el ubicado en Calle el Salitre Esquina Calle Guayana No. 201, Fraccionamiento Ojocaliente II, Aguascalientes, Aguascalientes, C.P. 20196, en donde se encuentra ubicado el Taller Infantil de Artes Plásticas, la Secretaría de la Función Pública deberá realizar los actos jurídicos que resulten necesarios, a efecto de transmitir a título gratuito a favor del Instituto la titularidad de los derechos que correspondan a la Federación sobre los mencionados inmuebles.</p>','transitorio',129,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('e3ce91af-9e3a-5ad7-8f7a-56183a3120b3'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Cuarto','<p>CUARTO.- Las personas que a la entrada en vigor de la presente Ley presten un servicio personal subordinado al Instituto Nacional de Estadística, Geografía e Informática, formarán parte del personal al servicio del Instituto, y conservarán las remuneraciones y prestaciones de las cuales gozan a la entrada en vigor de esta Ley.</p>','transitorio',130,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('934dab15-df5c-5828-81bc-dd8dd1a7f486'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Quinto','<p>QUINTO.- Los traspasos de recursos humanos, financieros y materiales del órgano desconcentrado Instituto Nacional de Estadística, Geografía e Informática, al organismo Instituto Nacional de Estadística y Geografía, deberán efectuarse en los términos de las disposiciones legales aplicables, garantizando la continuidad de la operación y de las actividades del Instituto.</p>','transitorio',131,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('17b50cd3-f9c5-51b7-bbe6-2ad0f1ca97ef'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Sexto','<p>SEXTO.- Para los efectos del transitorio Cuarto del Decreto por el que se declaran reformados los artículos 26 y 73 fracción XXIX-D de la Constitución Política de los Estados Unidos Mexicanos, publicado en el Diario Oficial de la Federación el 7 de abril de 2006, en los Presupuestos de Egresos de la Federación deberán incluirse, en adición a los recursos a que se refiere el segundo párrafo del artículo 83 de esta Ley, los recursos suficientes para que el Instituto continúe realizando las Actividades Estadísticas y Geográficas que de manera regular y periódica hayan sido realizadas por el Instituto Nacional de Estadística, Geografía e Informática hasta antes de la entrada en vigor del presente ordenamiento.</p>','transitorio',132,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('f5baa28b-440d-54ec-8761-9d4971c9edea'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Séptimo','<p>SÉPTIMO.- El Instituto contará con un plazo de 3 meses, contados a partir de la entrada en vigor de la presente Ley, para dar cumplimiento a lo dispuesto en el artículo 100 del presente ordenamiento por lo</p><p>que se refiere a las últimas encuestas nacionales publicadas; y con un plazo de 2 años para el resto de las encuestas nacionales y operativos censales concluidos, de conformidad con el calendario que al efecto dé a conocer la Junta de Gobierno dentro de los 90 días siguientes a la entrada en vigor de este ordenamiento.</p>','transitorio',133,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('bdd9a0a7-9cde-5d67-ba34-ca66057bdf67'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Octavo','<p>OCTAVO.- El Reglamento Interior del Instituto deberá expedirse en un plazo no mayor de seis meses, contados a partir del día en que quede legalmente instalada la Junta de Gobierno. En tanto se expida el citado Reglamento continuarán aplicándose, en lo que no se opongan a la presente Ley, los artículos 102 y 103 del Reglamento Interior de la Secretaría de Hacienda y Crédito Público.</p><p>En tanto el Instituto expide las demás disposiciones administrativas a que se refiere esta Ley, seguirán aplicándose las emitidas con anterioridad a su vigencia, en las materias correspondientes en lo que no se opongan a la presente Ley y continuará en vigor el Sistema Integral de Profesionalización del Instituto Nacional de Estadística, Geografía e Informática, publicado en el Diario Oficial de la Federación el 11 de noviembre de 1994. Las medidas administrativas dictadas con fundamento en disposiciones que por esta Ley se derogan, continuarán en vigor hasta que no sean revocadas o modificadas expresamente por las autoridades competentes.</p>','transitorio',134,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('71d33b23-97e7-5f4b-a251-98042387963d'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Noveno','<p>NOVENO.- Los poderes, mandatos y en general las representaciones otorgadas y facultades concedidas por el Instituto Nacional de Estadística, Geografía e Informática, con anterioridad a la entrada en vigor de la presente Ley, subsistirán en sus términos en tanto no sean modificados o revocados expresamente.</p><p>En el supuesto de que existan asuntos en la Secretaría de la Función Pública o en el Órgano Interno de Control en el Instituto Nacional de Estadística, Geografía e Informática, que se encuentren en trámite o pendientes de resolución a la fecha de entrada en vigor de la presente Ley, deberán ser concluidos respectivamente por la propia Secretaría de la Función Pública o por la Contraloría Interna del Instituto, aplicando lo dispuesto en la Ley Federal de Responsabilidades Administrativas de los Servidores Públicos y demás ordenamientos legales aplicables en la materia.</p>','transitorio',135,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('fc21f20c-0d84-511b-b027-ab798afcf23d'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Décimo','<p>DÉCIMO.- La Junta de Gobierno deberá aprobar y publicar en el Diario Oficial de la Federación a más tardar en el mes de diciembre de 2007, el Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica, el Programa Nacional de Estadística y Geografía, y el primer Programa Anual de Estadística y Geografía a que se refiere esta Ley.</p><p>En tanto se expiden los programas a que se refiere el párrafo anterior, el Instituto seguirá aplicando en todo lo que no se oponga a la presente Ley los programas que se hubieren emitido a efecto de realizar las tareas a cargo del Instituto.</p>','transitorio',136,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('5a14fb4f-e65a-5acd-8d0d-59e733df818e'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Décimo Primero','<p>DÉCIMO PRIMERO.- Dentro de los diez días hábiles siguientes a la entrada en vigor del presente Decreto, el Banco de México y el Instituto formarán un grupo de trabajo que tendrá como objetivo planear e instrumentar la transferencia al segundo, del cálculo y publicación de los índices nacionales de precios a que se refiere el artículo 59 de esta Ley. A partir de la entrada en vigor de la fracción III del artículo 59, el Instituto publicará los referidos índices nacionales de precios, por lo que cualquier referencia a los citados índices a cargo del Banco de México, se entenderá efectuada, a partir de esa fecha, al que publique el Instituto.</p><p>A partir de la publicación del presente Decreto, y hasta el día anterior a la entrada en vigor de la fracción III del artículo 59, el Banco de México continuará publicando los índices a que se refiere el párrafo anterior, con la participación creciente del Instituto.</p><p>A partir de la entrada en vigor de la fracción III del artículo 59, el Banco de México tendrá acceso, sin restricción alguna, a la metodología, bases de datos, información y procedimientos utilizados por el Instituto para calcular los índices nacionales a que se refiere este precepto.</p>','transitorio',137,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('76b36833-3b41-5641-aa11-33ecbcb8bfee'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Décimo Segundo','<p>DÉCIMO SEGUNDO.- Cuando las leyes, reglamentos, decretos, acuerdos u otros ordenamientos jurídicos hagan mención a la Ley de Información Estadística y Geográfica, o al Instituto Nacional de Estadística, Geografía e Informática, la referencia se entenderá hecha a la presente Ley y al Instituto Nacional de Estadística y Geografía, respectivamente.</p>','transitorio',138,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('ae0661e8-e925-59de-9c09-2af8cfcd2877'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Décimo Tercero','<p>DÉCIMO TERCERO.- La Junta de Gobierno contará con un plazo de ciento ochenta días, contados a partir de la designación de sus primeros miembros, para: determinar aquella información que formará parte del Acervo de Información Estadística y Geográfica a que se refiere el Título Tercero, Capítulo III de esta Ley, y hacer del conocimiento del público, a través de Internet, las metodologías que hasta antes de la entrada en vigor de la presente Ley se hubieren utilizado para la producción de dicha información.</p>','transitorio',139,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('45ba5cfa-a4fb-501d-a275-53e18acc11b1'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Décimo Cuarto','<p>DÉCIMO CUARTO.- A la entrada en vigor de la presente Ley, los comités técnicos sectoriales, regionales y especiales de estadística y de información geográfica que se hubieren constituido conforme a lo dispuesto en las fracciones II, III y IV del artículo 24 de la Ley de Información Estadística y Geográfica, y que se encuentren en funcionamiento, habrán de considerarse como Comités Técnicos Especializados a que se refiere el artículo 31 de esta Ley.</p>','transitorio',140,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('00a78854-2279-56b6-8914-4e1d4481800c'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Décimo Quinto','<p>DÉCIMO QUINTO.- Los acuerdos, anexos de ejecución, bases, contratos y convenios, que el Instituto Nacional de Estadística, Geografía e Informática haya suscrito hasta antes de la entrada en vigor de la presente Ley, se entenderán referidos al Instituto Nacional de Estadística y Geografía.</p>','transitorio',141,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('954264f8-b3ed-566c-9d40-58c9b79cad31'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Décimo Sexto','<p>DÉCIMO SEXTO.- La Información que al momento de la entrada en vigor de la presente Ley estuviere en proceso de generación por parte de las Unidades, deberá apegarse a las disposiciones que al efecto emita el Instituto.</p>','transitorio',142,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
insert into public.articulos (id,ley_id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre) values ('8e7eae1e-d47d-51a4-819c-c2133324a0e5'::uuid,'9ddee653-dfae-5c29-a4c9-5075417d4495'::uuid,'Transitorio Décimo Séptimo','<p>DÉCIMO SÉPTIMO.- Se abroga la Ley de Información Estadística y Geográfica y las demás disposiciones que se opongan a la presente Ley.</p>','transitorio',143,'Transitorios',null,'Ley publicada el 16 de abril de 2008') on conflict (id) do update set identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,orden=excluded.orden,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre;
